quests[13679] = { id = 13679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung des Streiters", description = "Ihr habt hart trainiert, <Streiter/Streiters> {name}, und nun ist die Zeit gekommen, Euer Können im berittenen Kampf gegen einen geschickten Gegner auf die Probe zu stellen.\n\nNehmt Eure Lanze, geht dann zu den angebundenen Reittieren außerhalb des Pavillons und steigt auf das Streitross der Quel'dorei, das dort untergebracht ist.\n\nIm Ring der Streiter auf der nördlichen Seite des Turnierplatzes werdet Ihr Knappe David vorfinden. Er wird sich vergewissern, dass Ihr bereit seid zu kämpfen, und Euren Widersacher herbeirufen.\n\nViel Glück, {name}. Möget Ihr stets sicher im Sattel sitzen und Eure Pfeile ins Schwarze treffen.", sourceObjective = "Sprecht mit Knappe David und ruft Euren Widersacher herbei. Kehrt zu Arkanist Taelist beim Argentumturnierplatz zurück, sobald Ihr den Argentumrecken besiegt habt.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", completion = "Meine gebührenden Glückwünsche, {name}. Ihr habt Euren Herausforderer geschlagen und Euch das Recht verdient, zum Recken aufzusteigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13680] = { id = 13680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung des Streiters", description = "Ihr habt hart trainiert, <Streiter/Streiterin> {name}, und nun ist die Zeit gekommen, Euer Können im berittenen Kampf gegen einen erfahrenen Gegner auf die Probe zu stellen.\n\nNehmt Eure Lanze, geht dann zu den angebundenen Reittieren außerhalb des Pavillons und steigt auf den Falkenschreiter der Sonnenhäscher.\n\nIm Ring der Streiter auf der nördlichen Seite des Turnierplatzes werdet Ihr ein Menschenkind, einen Knappen namens David, vorfinden. Er wird sich vergewissern, dass Ihr bereit seid zu kämpfen, und Euren Widersacher herbeirufen.\n\nViel Glück, {name}. Möget Ihr sicher im Sattel sitzen und Euer Pferd gleichmäßig reiten.", sourceObjective = "Sprecht mit Knappe David und ruft Euren Widersacher herbei. Kehrt zu Magister Edien Sonnental beim Argentumturnierplatz zurück, sobald Ihr den Argentumrecken besiegt habt.", completion = "Meine gebührenden Glückwünsche, {name}. Ihr habt Euren Herausforderer geschlagen und Euch das Recht verdient, zum Recken aufzusteigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13681] = { id = 13681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie der Block so der Splitter", description = "Stein für diesen Job zu besorgen war der reinste Alptraum, das kann ich Euch sagen! Es gibt in den Ruinen sichere Orte, an denen es tonnenweise Stein zu finden gibt, doch diese selbstgerechten Paladine wollen einfach nicht zugreifen. Hat was mit unbezahlbaren Artefakten zu tun, oder so was.\n\nWie dem auch sei: Darüber zu jammern wird auch nicht helfen, diesen Ort aufzubauen. In den Fußmarschen und der Bibliothek des Erfinders in den Sturmgipfeln gibt es eine ganze Reihe Titanenruinen. Nehmt meinen, ähm, 'Meißel' mit und seht, ob Ihr diese riesigen Blöcke nicht in brauchbare Stücke zerhauen könnt.", sourceObjective = "Bringt 15 kleine Steinblöcke zu Stümpi Sprengbolz beim Argentumturnierplatz.", sourceObjectiveStatus = "unverified-source-field" }
quests[13682] = { id = 13682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohung von oben", description = "Hochlord Tirion Fordring hat die Wachen verdoppelt, seitdem Ihr den Spitzel des Kults der Verdammten entlarvt habt. Seiner Meinung nach werden sie nicht aufhören, nur weil ihr Schwarzer Ritter besiegt wurde.\n\nUnsere Späher der Himmelsklauen haben davon berichtet, einen Frostwyrm namens Frostschlund gesichtet zu haben, der einen Stoßtrupp des Kults anführen soll. Wenn wir sie nicht abfangen, werden sie das Turnier angreifen. Laut den Berichten der Späher fliegt Frostschlund gen Südwesten und patrouilliert das Gebiet zwischen dem Eisenwallbollwerk und Aldur'thar.", sourceObjective = "Eadric der Reine beim Argentumturnierplatz möchte, dass Ihr Frostschlund und 3 Kultistenbombenschützen besiegt.", completion = "{name}, Ihr und Eure Verbündeten habt das Turnier vor einem vernichtenden Angriff bewahrt. Unsere Himmelsklauenreiter mögen zwar tapfer sein, haben jedoch alle Hände voll damit zu tun, den Frieden auf dem Turnierplatz zu wahren, und sie hätten Mühe damit, den Luftraum gegen die Angriffe des Kults zu verteidigen. Euch gehört der Dank des Argentumkreuzzugs und all derjenigen, die sich hier versammelt haben, um am Wettkampf teilzunehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13683] = { id = 13683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rituale aufhalten", description = "Ich habe zufällig mit angehört, welchen Verlust Illiyana erfahren musste. Ich kann ihren Wunsch nach Rache verstehen. Ich frage mich, ob Ihr, während Ihr diese ausführt, uns einen Dienst erweisen könntet?\n\nZweifellos habt Ihr bereits die Satyrn von Satyrnaar und Xavian gesehen, wie sie ekelhafte Rituale durchführen. Ich glaube, sie bereiten Rituale vor, die jeden der Nachtelfen, den sie fangen, in Satyrn verwandeln sollen. Wir Draenei möchten ebenfalls nicht, dass diese üble Magie sich verbreitet.\n\nWürdet Ihr die Ritualedelsteine stören während Ihr dort seid?", sourceObjective = "Stört 8 Ritualedelsteine.", completion = "Wir stehen in Eurer Schuld, {class}.\n\nDie Rituale können nicht mehr abgeschlossen werden und die Satyrn kämpfen nun auf verlorenem Posten, da sie ihre Anzahl nicht mehr mehren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[13684] = { id = 13684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Recke von Sturmwind", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner von Sturmwind anzutreten, {name}. Nun solltet Ihr mit Marschall Jacob Alerius sprechen, der Sturmwinds Wettkämpfer anführt. Als Großchampion von Sturmwind wird er Euch im Auftrag der Stadt für das Turnier anmelden. Außerdem wird er Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, {name}, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", sourceObjective = "Sprecht mit Marschall Jacob Alerius beim Argentumturnierplatz, um ein Recke von Sturmwind zu werden.", completion = "Na dann willkommen an Bord, Recke {name}. Die Delegation von Sturmwind ist stolz, Euch unter seinen Mitgliedern zählen zu dürfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13685] = { id = 13685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Recke von Eisenschmiede", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner von Eisenschmiede anzutreten, {name}. Nun solltet Ihr mit Lana Starkhammer sprechen, die die Wettkämpfer von Eisenschmiede anführt. Als Großchampion der Stadt wird sie Euch in ihrem Namen für das Turnier anmelden. Außerdem wird sie Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, {name}, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", sourceObjective = "Sprecht mit Lana Starkhammer beim Argentumturnierplatz, um ein Recke von Eisenschmiede zu werden.", completion = "Gut, Euch kennenzulernen, Recke. Eisenschmiede braucht Wettkämpfer wie Euch, um auf dem Turnier zu bestehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13686] = { id = 13686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Markierung für Allianzturniersqualifikation" }
quests[13687] = { id = 13687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Markierung für Hordeturniersqualifikation" }
quests[13688] = { id = 13688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Recke von Gnomeregan", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner von Gnomeregan anzutreten, {name}. Nun solltet Ihr mit Ambrose Bolzenfunk sprechen, der die Wettkämpfer von Gnomeregan anführt. Als Großchampion der Gnome wird er Euch in ihrem Namen für das Turnier anmelden. Außerdem wird er Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, {name}, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", sourceObjective = "Sprecht mit Ambrose Bolzenfunk beim Argentumturnierplatz, um ein Recke von Gnomeregan zu werden.", completion = "Na dann willkommen an Bord, Recke {name}. Die Delegation von Gnomeregan ist stolz, Euch unter seinen Mitgliedern zählen zu dürfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13689] = { id = 13689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Recke von Darnassus", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner von Darnassus anzutreten, {name}. Nun solltet Ihr mit Jaelyne Abendlied sprechen, die die Wettkämpfer von Darnassus anführt. Als Großchampion der Nachtelfen wird sie Euch in ihrem Namen für das Turnier anmelden. Außerdem wird sie Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, {name}, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", sourceObjective = "Sprecht mit Jaelyne Abendlied beim Argentumturnierplatz, um ein Recke von Darnassus zu werden.", completion = "Willkommen zur Turniersdelegation von Darnassus, {name}. Es wird eine Freude sein, an Eurer Seite zu trainieren und am Wettkampf teilzunehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13690] = { id = 13690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Recke der Exodar", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner der Exodar anzutreten, {name}. Nun solltet Ihr Euch Kolosos vorstellen, dem Leiter der Delegation der Exodar. Als Großchampion der Draenei wird er Euch im Auftrag der Stadt für das Turnier anmelden. Außerdem wird er Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, {name}, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", sourceObjective = "Sprecht mit Kolosos beim Argentumturnierplatz, um ein Recke der Exodar zu werden.", completion = "Na dann willkommen an Bord, Recke {name}. Die Delegation der Exodar ist stolz, Euch unter seinen Mitgliedern zählen zu dürfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13691] = { id = 13691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Recke von Orgrimmar", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner von Orgrimmar anzutreten, {name}. Nun solltet Ihr mit Mokra dem Schädelberster sprechen, der Orgrimmars Wettkämpfer anführt. Als Großchampion von Orgrimmar wird er Euch im Auftrag der Stadt für das Turnier anmelden. Außerdem wird er Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, {name}, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", sourceObjective = "Sprecht mit Mokra dem Schädelberster beim Argentumturnierplatz, um ein Recke von Orgrimmar zu werden.", completion = "Ihr wollt also für Orgrimmar antreten? Nur, weil Ihr ein paar Attrappen verhauen habt, heißt das noch lange nicht, dass Ihr auch gewinnen werdet. Doch von nun an werdet Ihr mit den Besten zusammen trainieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13692] = { id = 13692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schwert und die See", description = "Mein Schwert ist auf See verloren gegangen. Holt es herauf und bringt es zurück!", sourceObjective = "Der alte Barlo im Kristallsangwald möchte, dass Ihr ihm das Schwert der Ritterwürde bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13693] = { id = 13693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Recke von Sen'jin", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner von Sen'jin anzutreten, {name}. Nun solltet Ihr mit Zul'tore sprechen, der die Krieger von Sen'jin anführt. Als Großchampion der Trolle wird er Euch im Auftrag der Stadt für das Turnier anmelden. Außerdem wird er Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, {name}, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", sourceObjective = "Sprecht mit Zul'tore beim Argentumturnierplatz, um ein Recke von Sen'jin zu werden.", completion = "Ihr denkt, dass Ihr das Zeug dafür habt, in Sen'jins Namen am Wettkampf teilzunehmen? Wir werden es herausfinden, denke ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[13694] = { id = 13694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Recke von Donnerfels", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner von Donnerfels anzutreten, {name}. Nun solltet Ihr mit Runok Wildmähne sprechen, der Donnerfels' Wettkämpfer anführt. Als Großchampion von Donnerfels wird er Euch im Auftrag der Stadt für das Turnier anmelden. Außerdem wird er Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, {name}, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", sourceObjective = "Sprecht mit Runok Wildmähne beim Argentumturnierplatz, um ein Recke von Donnerfels zu werden.", completion = "Im Namen von Donnerfels und seinen Kriegern heiße ich Euch willkommen, {name}. Kämpft unter unserem Banner stets mit Ehre und Tapferkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[13695] = { id = 13695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Recke von Unterstadt", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner von Unterstadt anzutreten, {name}. Nun solltet Ihr mit Todespirscher Visceri sprechen, der Unterstadts Wettkämpfer anführt. Als Großchampion wird er Euch im Auftrag der Stadt für das Turnier anmelden. Außerdem wird er Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, {name}, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", sourceObjective = "Sprecht mit Todespirscher Visceri beim Argentumturnierplatz, um ein Recke von Unterstadt zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[13696] = { id = 13696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Recke von Silbermond", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner von Silbermond anzutreten, {name}. Nun solltet Ihr mit Eressea Morgensänger sprechen, die Silbermonds Wettkämpfer anführt. Als Großchampion von Silbermond wird sie Euch im Auftrag der Stadt für das Turnier anmelden. Außerdem wird sie Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, {name}, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", sourceObjective = "Sprecht mit Eressea Morgensänger beim Argentumturnierplatz, um ein Recke von Silbermond zu werden.", completion = "Ihr wollt also für Silbermond antreten? Nun gut. Ich werde Euch in die Namensliste aufnehmen und Ihr könnt sofort damit anfangen, mit den anderen Recken zusammenzuarbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13697] = { id = 13697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wappen des Recken", description = "In Eurer Ausbildung zum Recken habt Ihr die Möglichkeit, Euer Können gegen Recken der anderen Städte auf die Probe zu stellen. Obwohl diese Kämpfe nicht zum formalen Teil des Wettkampfes gehören, werdet Ihr wertvolle Lektionen in Sachen Kampfstil erhalten und Schwächen Eurer Widersacher entdecken.\n\nRecken sind ein beherzter Haufen - sie konkurrieren untereinander um Ehre und Ruf.\n\nFührt Eure Ausbildung so lange fort, bis Ihr von Eurem Können überzeugt seid und all Eure Gegner schlagen könnt, um mir dann die Siegel zu bringen, die Ihr errungen habt.", sourceObjective = "Bringt 25 Siegel des Recken zu Mokra dem Schädelberster beim Argentumturnierplatz.", progress = "Seid Ihr bereit zu zeigen, wie gut Ihr die Fähigkeiten des Recken beherrscht?", completion = "Beeindruckend, Recke. Ich werde die Vorbereitungen für Eure Prüfung umgehend treffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13698] = { id = 13698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprengstoffschreddern", description = "Ich hasse es, Euch wieder dorthin zurückzuschicken, aber Eurer Beschreibung entnehme ich, dass wir es nicht zulassen dürfen, dass sie den ganzen Sprengstoff verwenden, den sie gelagert haben!\n\nEs ist zu gefährlich für Euch, ihn einfach so zu zerstören, aber wenn Ihr einen der Schredder stehlen könntet, bin ich mir sicher, dass er robust genug ist, den Explosionen standzuhalten.\n\nNachdem Ihr den Sprengstoff vernichtet habt, kehrt mit dem Schredder wieder hierher zurück. Es wäre närrisch, ihn wieder der Horde zu überlassen.", sourceObjective = "Verwendet einen Kriegshymnenschredder um 8 Fässer mit Sprengstoff zu vernichten.", completion = "Ich habe die Explosionen bis hierher sehen können! Diesen widerwärtigen Orcs und ihren Goblinlakaien wird es nun schwer fallen, den Wald weiter zu zerstören!\n\nWir können Euch nicht genug danken, {name}. Bitte nehmt dies.", sourceObjectiveStatus = "unverified-source-field" }
quests[13699] = { id = 13699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung des Recken", description = "Ihr seid fast bereit, im Namen Sturmwinds beim großen Arenakampf anzutreten. Um zu beweisen, dass Ihr würdig seid, für unsere Stadt in die Listen aufgenommen zu werden, müsst Ihr einen Champion des Argentumkreuzzugs besiegen.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und sattelt auf. Sprecht dann mit Knappe Danny im Ring der Recken des Argentumkreuzzugs am westlichen Rand des Platzes. Er wird dann Euren Gegner herbeirufen, sobald Ihr bereit seid.\n\nNachdem der Kampf entschieden ist, werden wir uns über das Resultat unterhalten.", sourceObjective = "Sprecht mit Knappe Danny, um Euren Gegner herbeizurufen. Kehrt zu Marschall Jacob Alerius beim Argentumturnierplatz zurück, sobald Ihr den Argentumchampion besiegt habt.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", completion = "Ihr habt Euch für den Titel des Champions als würdig erwiesen, {name}. Ihr werdet im Namen Sturmwinds auf der höchsten Stufe des Turniers antreten und im großen Arenakampf reiten, Eure Waffe bereit und Eure beeindruckende Standarte im Rücken.", sourceObjectiveStatus = "unverified-source-field" }
quests[13700] = { id = 13700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Markierung für Champion der Allianz" }
quests[13701] = { id = 13701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Markierung für Champion der Horde" }
quests[13702] = { id = 13702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg eines Champions", description = "Herzlichen Glückwunsch, {name}. Ihr habt viele Kampfesarten gemeistert und all die Herausforderungen bewältigt, denen Ihr Euch gestellt habt. Ihr seid zweifellos dazu bereit, gegen die besten Krieger des Turniers anzutreten - den Champions der Hauptstädte.\n\nJustiziarin Mariel Treuherz hat darum gebeten, mit Euch zu sprechen, {name}, und Euch offiziell beim großen Arenakampf der Champions anzumelden.", sourceObjective = "Sprecht mit Justiziarin Mariel Treuherz beim Argentumturnierplatz.", completion = "Ich heiße Euch als einen der Champions des Turniers willkommen, {name}. Ihr werdet um den Großmeistertitel des Turniers kämpfen können. Außerdem habt Ihr die Wahl, ein Recke der Delegation einer anderen Allianzstadt zu werden und mit der Zeit auch einer ihrer Champions.\n\nAlle Champions müssen von einem Knappen unterstützt werden, {name}, Ihr mit eingeschlossen. Erlaubt mir, einen der unsrigen zu Eurem Knappen zu machen, um Euch im Kampf zur Seite zu stehen. Er wird mit Stolz das Banner jeder Stadt tragen, die Euch zum Champion ernannt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13703] = { id = 13703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recke von Eisenschmiede", description = "Seid willkommen, Champion. Ich habe schon von Euren Kampffertigkeiten gehört. Wollt Ihr der Turniersdelegation von Eisenschmiede beitreten?\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch sobald man Euch zum Champion von Eisenschmiede ernannt hat, wird Euer Knappe unser Banner in die Schlacht tragen dürfen.", sourceObjective = "Sprecht wieder mit Lana Starkhammer, falls Ihr ein Recke von Eisenschmiede werden wollt.", completion = "Wir sind stolz, dass Ihr Euch dazu entschlossen habt, uns beizutreten, und ich weiß, dass Ihr auf dem Schlachtfeld glänzen werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[13704] = { id = 13704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recke von Gnomeregan", description = "Seid willkommen, Champion. Ich habe schon von Euren Kampffertigkeiten gehört. Gnomeregans Delegation könnte von jemandem wie Euch wirklich profitieren.\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch wenn man Euch zum Champion von Gnomeregan ernannt hat, wird Euer Knappe die Möglichkeit haben, unser Banner in die Schlacht zu tragen.", sourceObjective = "Sprecht wieder mit Ambrose Bolzenfunk, falls Ihr ein Recke von Gnomeregan werden wollt.", completion = "Wir sind stolz, Euch unter uns zählen zu dürfen, {name}, und wir freuen uns darauf, mit Euch zu trainieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13705] = { id = 13705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recke der Exodar", description = "Seid willkommen, Champion. Ich habe schon von Euren Heldentaten gehört. Wollt Ihr der Turniersdelegation der Exodar beitreten?\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch sobald man Euch zum Champion der Exodar ernannt hat, wird Euer Knappe die Möglichkeit haben, unser Banner in die Schlacht zu tragen.", sourceObjective = "Sprecht wieder mit Kolosos, falls Ihr ein Recke der Exodar werden wollt.", completion = "Es ist gut, dass Ihr nun zu uns gehört, {name}. Wir werden alle vom Training mit Euch profitieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13706] = { id = 13706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recke von Darnassus", description = "Seid willkommen, Champion. Ich habe von Euren Leistungen gehört und wir wären geehrt, wenn Ihr der Delegation von Darnassus beitreten würdet.\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch wenn man Euch zum Champion von Darnassus ernannt hat, wird Euer Knappe die Möglichkeit haben, unser Banner in die Schlacht zu tragen.", sourceObjective = "Sprecht wieder mit Jaelyne Abendlied, falls Ihr ein Recke von Darnassus werden wollt.", completion = "Die {class} von Darnassus sind geehrt, an Eurer Seite kämpfen und trainieren zu dürfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13707] = { id = 13707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recke von Orgrimmar", description = "Ihr seid also ein Champion geworden? Dann habt Ihr Euch als würdiger Kämpfer erwiesen und ich wäre stolz, Euch in Orgrimmars Delegation begrüßen zu dürfen.\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hochklettern, doch sobald man Euch zum Champion von Orgrimmar ernannt hat, wird Euer Grunzling die Möglichkeit haben, unser Banner in die Schlacht zu tragen.", sourceObjective = "Sprecht wieder mit Mokra dem Schädelberster, falls Ihr ein Recke von Orgrimmar werden wollt.", completion = "Dann seid willkommen, {name}. Ich freue mich darauf, Euch beim Training mit meinen Männern zuzusehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13708] = { id = 13708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recke von Sen'jin", description = "Grüße, Champion. Wenn Ihr wollt, dann würde ich Euch in Sen'jins Turniersdelegation willkommen heißen.\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hochklettern, doch sobald man Euch zum Champion von Sen'jin ernannt hat, wird Euer Grunzling die Möglichkeit haben, unser Banner in die Schlacht zu tragen.", sourceObjective = "Sprecht wieder mit Zul'tore, falls Ihr ein Recke von Sen'jin werden wollt.", completion = "Ich bin froh, dass Ihr Euch dazu entschlossen habt, uns beizutreten, und freue mich darauf, Euch in Aktion zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13709] = { id = 13709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recke von Donnerfels", description = "Willkommen, Champion. Als Großchampion der Delegation von Donnerfels wäre ich stolz darauf, Euch in unseren Reihen begrüßen zu dürfen, falls Ihr dies wünscht.\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch wenn man Euch zum Champion von Donnerfels ernannt hat, wird Euer Grunzling die Möglichkeit haben, unser Banner in die Schlacht zu tragen.", sourceObjective = "Sprecht wieder mit Runok Wildmähne, falls Ihr ein Recke von Donnerfels werden wollt.", completion = "Es ehrt mich, dass Ihr Euch dazu entschlossen habt, unserer Delegation beizutreten. Ich weiß, dass Ihr uns stolz machen werdet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13710] = { id = 13710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recke von Unterstadt", description = "Seid willkommen, Champion. Die Delegation der Verlassenen könnte immer so jemanden wie Euch gebrauchen. Wollt Ihr uns beitreten?\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch wenn man Euch zum Champion von Unterstadt ernannt hat, wird Euer Grunzling die Möglichkeit haben, unser Banner in die Schlacht zu tragen.", sourceObjective = "Sprecht wieder mit Todespirscher Visceri, falls Ihr ein Recke von Unterstadt werden wollt.", completion = "Ihr habt eine weise Entscheidung getroffen, {name}. Wir beide werden von dieser Abmachung profitieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13711] = { id = 13711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recke von Silbermond", description = "Ihr seid also ein Champion geworden? Dann habt Ihr Euch als würdiger Kämpfer erwiesen und ich wäre stolz, Euch in Silbermonds Delegation begrüßen zu dürfen.\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch sobald man Euch zum Champion von Silbermond ernannt hat, wird Euer Grunzling die Möglichkeit haben, unser Banner in die Schlacht zu tragen.", sourceObjective = "Sprecht wieder mit Eressea Morgensänger, falls Ihr ein Recke von Silbermond werden wollt.", completion = "Es wird uns eine Ehre sein, mit Euch zu trainieren und am Wettkampf teilzunehmen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13712] = { id = 13712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettung in der Not", description = "Ihr kommt mit mir mit, {name}.\n\nIch kann niemanden sonst erübrigen und wir können es uns nicht leisten, den Splitterholzposten zu verlieren.\n\nBereitet Euch gut vor und sprecht mich wieder an, wenn Ihr so weit seid.", sourceObjective = "Sprecht mit Kadrak am Schutzwall von Mor'shan und begleitet ihn zum Splitterholzposten.", progress = "Arbeit abgeschlossen!", completion = "Gorkas Tod war nicht umsonst, {name}.\n\nDer Splitterholzposten wäre sicher gefallen, wenn wir nicht rechtzeitig gekommen wären.\n\nJetzt müssen wir uns daran machen, die Verteidigung wieder aufzubauen.\n\nEs ist noch nicht vorbei...", sourceObjectiveStatus = "unverified-source-field" }
quests[13713] = { id = 13713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung des Recken", description = "Ihr seid fast bereit, im Namen von Eisenschmiede beim großen Arenakampf anzutreten. Um zu beweisen, dass Ihr würdig seid, für unsere Stadt in die Listen aufgenommen zu werden, müsst Ihr einen Champion des Argentumkreuzzugs besiegen.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und sattelt auf. Sprecht dann mit Knappe Danny im Übungsring der Recken am westlichen Rand des Platzes. Er wird dann Euren Gegner herbeirufen.\n\nNachdem der Kampf entschieden ist, werden wir uns über das Resultat unterhalten.", sourceObjective = "Sprecht mit Knappe Danny, um Euren Gegner herbeizurufen. Kehrt zu Lana Starkhammer beim Argentumturnierplatz zurück, sobald Ihr den Argentumchampion besiegt habt.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", completion = "Ihr habt Euch für den Titel des Champions als würdig erwiesen, {name}. Ihr werdet im Namen von Eisenschmiede auf der höchsten Stufe des Turniers antreten und im großen Arenakampf reiten, Eure Waffe bereit und Eure beeindruckende Standarte im Rücken.", sourceObjectiveStatus = "unverified-source-field" }
