quests[13785] = { id = 13785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Winters Schneide", description = "Verflucht soll dieser Todesritter dafür sein, mein Schwert zerbrochen zu haben!\n\nIm südlichen Teil des Kristallsangwalds, über dem Ausgang der Kristallschlucht, werdet Ihr Lord Immerflamm finden. Tötet ihn und entnehmt seinen Überresten die ewig brennende Glut.\n\nBringt sie zur Mitte des Winterhauchsees im Norden des Heulenden Fjords und befreit damit die in Eis eingeschlossene Maid. Sie ist die Wächterin eines uralten Schwerts und wird es einem jeden überreichen, der sie befreit.\n\nZeigt, was Ihr wert seid und verdient Euch die Waffe, die sie nun schon so lange bewacht, {name}.", sourceObjective = "Eressea Morgensänger beim Argentumturnierplatz möchte, dass Ihr ihr Winterschneide bringt.", progress = "Habt Ihr die Klinge ergattert?", completion = "Die Klinge ist so wundervoll, wie die Geschichten es verheißen. Es gibt wohl kaum einen triftigen Grund, die Reparaturen an einem gewöhnlichen Schwert abzuschließen. Die Winterschneide ist ihm bei weitem überlegen und ich werde sie in Zukunft tragen. Ihr habt meinen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13786] = { id = 13786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldübungen eines Recken", description = "Das Turnier ist eine Gelegenheit, um Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Neben der Verfeinerung Eurer Fertigkeiten solltet Ihr auch Eure Bissigkeit im Kampf gegen Euren Gegner schärfen.\n\nReist in die Gegend südwestlich des Tals der Gefallenen Helden und nördlich von Corp'rethar. Die Geißel lässt dort tote Helden auferstehen und wiegelt sie gegen uns auf. Besiegt diese Diener der Geißel, macht unseren Verbündeten alle Ehre und haltet Euch bereit für den Kampf.", sourceObjective = "Kethiel Sonnenlanze beim Argentumturnierplatz möchte, dass Ihr 10 konvertierte Helden tötet.", completion = "Einen ganzen Tag zu trainieren kann nie schaden. Gut zu sehen, dass Ihr in Übung bleibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13787] = { id = 13787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Arenakampf", description = "Der große Arenakampf ist der wichtigste Wettkampf des Turniers. Der Sieg wird nicht leicht zu erringen sein, doch ich bin überzeugt, dass wir gewinnen werden. Ihr müsst so lange mit Eurem Reittier trainieren, bis Ihr eins mit ihm seid.\n\nEs wird helfen, Euch auf die Härte des Turnierkampfes vorzubereiten.\n\nGeht zu den Reittieren außerhalb des Pavillons, nehmt Eure Lanze, steigt auf den Falkenschreiter von Silbermond, der dort steht, und fordert die Recken heraus. Sie warten im Ring der Recken der Horde gleich außerhalb unseres Zelts.", sourceObjective = "Bringt 3 Male des Recken zu Aneera Thuron beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", progress = "Habt Ihr Euer Training für den großen Arenakampf abgeschlossen?", completion = "Mit den anderen Recken zu trainieren wird Eure Krallen und Euren Kampfinstinkt schärfen. Ihr werdet bereit sein, wenn der Wettkampf beginnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13788] = { id = 13788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohung von oben", description = "Der Argentumkreuzzug hat die Wachen verdoppelt, seitdem Ihr den Spitzel des Kults der Verdammten entlarvt habt. Man weiß dort, dass die Kultisten nicht eher haltmachen werden, bis dieser Ort hier vernichtet und verhindert wurde, dass das Turnier stattfindet.\n\nDie Kundschafter des Argentumkreuzzugs haben davon berichtet, einen Frostwyrm namens Frostschlund gesichtet zu haben, der einen Stoßtrupp des Kults anführen soll.\n\nIhr müsst sie abfangen und beseitigen, bevor sie angreifen. Laut den Berichten der Späher fliegt Frostschlund gen Südwesten im Gebiet zwischen dem Eisenwallbollwerk und Aldur'thar herum.", sourceObjective = "Crok Geißelbann beim Argentumturnierplatz möchte, dass Ihr Frostschlund und 3 Kultistenbombenschützen besiegt.", completion = "{name}, Ihr habt das Turnier vor einem vernichtenden Angriff bewahrt. Der Argentumkreuzzug und all jene, die hier versammelt sind, stehen in Eurer Schuld und wir werden dafür sorgen, dass sie sich auch daran erinnern. Die Friedensbewahrer und Himmelsklauen machen so einen Wind darum, Schutz zu bieten, doch sie verbringen mehr Zeit damit, Schlägereien zwischen Betrunkenen aufzulösen, als uns vor der Geißel zu beschützen.\n\nMacht nichts - wir beschützen immer die unseren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13789] = { id = 13789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht zum Gegner tragen", description = "Das Kolosseum befindet sich im gefährlichsten Teil der Welt, {name}. Blut und Qualen waren der Preis, den wir bezahlen mussten, um dieses Gebiet der Geißel abzunehmen; trotzdem schlägt unser Gegner mit einer scheinbar unerschöpflichen Armee weiterhin zurück. Und was die Sache noch schlimmer macht, ist, dass diese untote Armee von sterblichen Sympathisanten unterstützt wird - dem Kult der Verdammten.\n\nGeht nach Eiskrone und tötet jeden Kultisten, der Euch in die Quere kommt.", sourceObjective = "Cellian Tagesanbruch beim Argentumturnierplatz möchte, dass Ihr 15 Anhänger des Kults der Verdammten tötet. Dazu zählen alle Anhänger des Kults der Verdammten im Bereich von Eiskrone.", completion = "Ihr seid ein wahrer Champion, {name}, im Ring und auf dem Schlachtfeld. Wir alle müssen wachsam gegenüber der Geißel sein und Ihr seid unseren Brüdern und Eurem eigenen Volke ein Beispiel.", sourceObjectiveStatus = "unverified-source-field" }
quests[13790] = { id = 13790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter Champions", description = "Als Champion habt Ihr die Kunst des berittenen Kampfes zur Vollendung gebracht, habt Herausforderer aller Klassen bezwungen. Diejenigen, die Ihr besiegt habt, werden bis zum Beginn des Turniers ihre Anstrengungen verdoppelt haben und danach trachten, ihren Verlust zu rächen, den sie durch Euch erfahren mussten.\n\nEs wäre Euch anzuraten, im Kampf mit den Streitern, die im Ring der Champions auf Euch warten, Eure Fähigkeiten zu verbessern. Nehmt Eure Lanze, geht zur Südseite des Platzes, besteigt eines der Euch zur Verfügung stehenden, angebundenen Reittiere und fordert sie heraus.", sourceObjective = "Bringt 4 Male des Champions zu Luuri beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", progress = "Habt Ihr Euer Training mit den anderen Champions beendet?", completion = "Gut gemacht. Mit den anderen Champions zu trainieren ist einer der besten Wege, Euch auf den Turnierwettkampf vorzubereiten. Ich weiß, dass Ihr die Allianz stolz machen werdet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13791] = { id = 13791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht zum Gegner tragen", description = "Es wird gut tun, bei all unseren Scheinkämpfen nicht zu vergessen, dass wir vom wahren Feind umgeben werden. Der Argentumkreuzzug möchte über einen Wettbewerb die besten Kämpfer ausfindig machen, doch das wäre schon mit denjenigen getan, die von der Schlacht zurückkehren. Lasst uns den Paladinen zeigen, dass wir willens sind, die Schlacht zum Kult der Verdammten zu tragen, selbst während wir uns auf das Turnier vorbereiten.\n\nGeht nach Eiskrone und tötet jeden Kultisten, dem Ihr begegnet. Sie sind besonders stark um Aldur'thar und Todessprechers Wacht vertreten.", sourceObjective = "Zor'be der Blutvergießer beim Argentumturnierplatz möchte, dass Ihr 15 Anhänger des Kults der Verdammten tötet. Dazu zählen alle Kultisten im Bereich von Eiskrone.", completion = "Ihr habt gute Arbeit dabei geleistet zu zeigen, dass wir unserer Verpflichtung nachkommen und die Geißel bekämpfen, egal wo wir sind oder was wir tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[13792] = { id = 13792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schattenwandler", description = "Jetzt, wo die Dämonentore zerstört sind, muss die Kraft des Waldes wieder regeneriert werden. Das Herz des Waldes muss wiedererlangt werden!\n\nGaivan Schattenwandler, ein mächtiger Druide der Klaue ist Richtung Südwesten am Dämonenhügel vorbei zum Grabhügel von Dor'Danil gegangen. Darin liegt das Herz des Waldes. Es wird von den Druiden des Eschentals tief unter der Oberfläche beschützt.\n\nSucht nach Gaivan und erzählt ihm, was sich zugetragen hat, {name}.", sourceObjective = "Sprecht mit Gaivan Schattenwandler, der vor dem Eingang zum Grabhügel von Dor'Danil im Eschental wandelt.", completion = "Ihr seid mutig, hierher zu kommen, {class}, aber Ihr seid vielleicht zu spät. All unsere Druiden sind entweder tot oder sind verrückt geworden.\n\nDennoch, Eure Geschichte ist faszinierend und wenn das, was Ihr sagt, wahr ist, dann muss Knorre das Herz des Waldes bald bekommen oder das Eschental wird vergehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13793] = { id = 13793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter Champions", description = "Als Champion habt Ihr die Kunst des berittenen Kampfes zur Vollendung gebracht, habt Herausforderer aller Klassen besiegt. Ihr müsst Euch sicher sein, dass Ihr jeden besiegen könnt, dem Ihr auf dem Turnier entgegentreten werdet.\n\nIhr solltet weiterhin an Euren eigenen Fertigkeiten feilen und mehr über die Schwächen Eurer Gegner erfahren. Champions aller Städte üben im Ring der Champions in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon. Geht dorthin, nehmt Eure Lanze, wählt irgendein Euch zur Verfügung stehendes Reittier aus und fordert sie heraus.", sourceObjective = "Bringt 4 Male des Champions zu Illyrie Nachtlauer beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", progress = "Habt Ihr Euer Training mit den anderen Champions beendet?", completion = "Ihr beherrscht den Umgang mit Eurem Reittier gut, {name}. Mit der Zeit werden Eure Gegner Euch fürchten lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13794] = { id = 13794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eadric der Reine", description = "Ich habe meine Brüder des Argentumkreuzzugs gebeten, eng mit denjenigen zusammenzuarbeiten, die zum Champion aufsteigen. Eadric der Reine, der Großchampion unserer Bruderschaft, hilft dabei, die Trainingsübungen für Champions aller Städte zu beaufsichtigen und sie bei ihren letzten Vorbereitungen für den Turnierwettkampf zu unterstützen.\n\nBitte geht nun und stellt Euch ihm vor. Ich bin mir sicher, dass er begierig darauf sein wird, Eure Bekanntschaft zu machen und Euch auf Eurem Weg zum Wettkampf mit Azeroths größten Champions zu begleiten.", sourceObjective = "Sprecht mit Eadric dem Reinen beim Argentumturnierplatz.", completion = "Gut, Euch endlich kennenzulernen, Champion. Der Hochlord hat mich gebeten, die Koordination der Champions in die Hand zu nehmen, um dafür zu sorgen, dass sie miteinander trainieren und die Verteidigung des Turnierplatzes verstärken.", sourceObjectiveStatus = "unverified-source-field" }
quests[13795] = { id = 13795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geißelbann", description = "Der Delegationsanführer der Ritter der Schwarzen Klinge hat darum gebeten, mit Euch zu sprechen, {class}. Crok Geißelbann ist ein äußerst furchterregender Kämpfer und ich hege keine Zweifel daran, dass er viel von Euch fordern wird.\n\nDie Ritter der Schwarzen Klinge haben auf der Nordseite des Turnierplatzes ihr Lager aufgeschlagen, westlich der Zeltbehausungen der Allianzdelegationen.", sourceObjective = "Sprecht mit Crok Geißelbann beim Argentumturnierplatz.", completion = "Ihr seid also ein Champion geworden, {name}. Ich hatte keine Zweifel daran, dass dies geschehen wird. Wir Ritter wurden in der Hitze des Kampfes ausgebildet, nicht an hölzernen Attrappen. Lasst uns den Paladinen und ihren Gästen zeigen, was die Schlacht aus uns gemacht hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13796] = { id = 13796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Herz des Waldes", description = "Ihr müsst das Herz des Waldes um jeden Preis zu Knorre bringen!\n\nEs liegt tief unten im Grabhügel von Dor'Danil - verdorben von der Horde. Nur Knorre kann es reinigen.\n\nUm es vom Fleck zu bewegen, braucht Ihr jedoch eine Kraft der Natur. Wenn Ihr ausreichend reine Erdgeister von den abtrünnigen Druiden und Bewahrern einsammelt, können die Erdgeister zu einer Kraft der Natur vereint werden.\n\nViel Glück, {name}!", sourceObjective = "Beschafft das Herz des Waldes.", progress = "{name}, Ihr seid zurückgekehrt.", completion = "Das Herz des Waldes! Es ist verdorben!\n\n<Das große Urtum knarrt, als seine gigantischen Gliedmaßen damit beginnen, ein Ritual durchzuführen.>\n\nBleibt zurück, {name}, ich werde versuchen, das Herz zu reinigen, bevor alles verloren ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[13797] = { id = 13797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemeinheiten", description = "Draaka benötigt eine Art von Magnet – etwas, das ihre dämonischen Geschosse anzieht.\n\n<Durak grinst verschlagen.>\n\nZufällig kenne ich eine Methode, die unserem Zwecke dienlich sein sollte.\n\nIhr sucht die Minen nach faustgroßen Erzklumpen ab, und ich bereite eine besondere... Verzauberung vor.", sourceObjective = "Durchsucht die Haufen frischen Gerölls, um 10 Erzklumpen zu finden.", progress = "Habt ihr die Erzklumpen eingesammelt, die wir brauchen?", completion = "Gute Arbeit! Sie sollten den Fluch für unsere Zwecke lange genug tragen können...", sourceObjectiveStatus = "unverified-source-field" }
quests[13798] = { id = 13798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Regen der Zerstörung", description = "Gerade rechtzeitig, {class}. Die Elfen haben einen weiteren Angriff gestartet!\n\nVerwendet das verfluchte Erz von den Wachtürmen aus, um die Ziele für Draaka zu markieren.\n\nIhre Projektile werden Eure Ziele treffen und magische Höllenflammen hervorbrechen lassen, die alle Feinde im Umfeld vernichten.\n\nEs gibt starke Vorurteile gegen den Gebrauch von dämonischer Magie. Unberechtigterweise, aber dennoch. Aus diesem Grund werde ich Euch für die Dauer der Mission in einen Wichtel verwandeln, um zu verhindern, dass man Euch erkennt.", sourceObjective = "Nutzt das verfluchte Erz, um Ziele für Draaka zu markieren. Ihr müsst 30 Nachtelfentruppen und 5 tobende Urtume töten.\n\nSprecht mit Durak, um die Wichtelverkleidung aufzufrischen.", progress = "Ist der Feind gefallen, {name}?", completion = "Habt Ihr das gespürt, {name}!?\n\nWie die reine Teufelskraft durch Euer Sein brodelt?\n\nDas ist mit nichts vergleichbar!", sourceObjectiveStatus = "unverified-source-field" }
quests[13799] = { id = 13799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo sind meine Schlüssel?", description = "Ich kann meine Schlüssel nicht finden! Sicher ist mein böser Zwilling schuld daran. Bitte \"kümmert\" Euch um ihn, {name}.", sourceObjective = "Dr. Finger möchte, dass Ihr seinen bösen Zwilling, Bösfinger, tötet und ihm seine Schlüssel abnehmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13800] = { id = 13800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holt meine Schlüssel!", description = "Holt sie!", sourceObjective = "Findet die Schlüssel von Dr. Finger.", sourceObjectiveStatus = "unverified-source-field" }
quests[13801] = { id = 13801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geisterelfen", description = "H-habt Ihr das gehört? Geister! Ich hasse Geister!\n\nIhr schauerliches Geheul kommt aus den Grabhügeln im Süden. Ahhh! Macht, dass sie aufhören!\n\nBitte, <mein Herr/gnädiges Fräulein>, ich zahle gutes Geld dafür, wenn Ihr mir diese Stimmen aus dem Kopf schafft!", sourceObjective = "Vernichtet 15 beliebige Nachtelfengeister in den Grabhügeln von Dor'Danil.", completion = "Wohooo!!\n\nIhr habt die Stimmen zum Schweigen gebracht! Habt Dank, vielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[13802] = { id = 13802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Goblin mit zwei Gehirnen", description = "Seht Ihr sie dort, entlang der Küste? Was für prächtige Exemplare! Seht Euch nur an, wie Ihre primitive Gesellschaft zusammenarbeitet, wie eine gut geölte Maschine, vom niedrigsten Arbeiter bis zu ihrem Anführer, den ich \"König Burgrurble\" genannt habe.\n\nIch muss einfach ihre Gehirne untersuchen.\"\n\nKönnt Ihr mir ein intaktes Stammhirn eines Sabberzahnmurlocs beschaffen? Tötet sie - für die Wissenschaft!", sourceObjective = "Bringt das Stammhirn eines Sabberzahnmurlocs zu Professor Flozz an der Küste.", sourceObjectiveStatus = "unverified-source-field" }
quests[13803] = { id = 13803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Blut der Schwachen", description = "Wir wussten, dass die Elfen sich nicht kampflos ergeben würden, aber niemand hatte damit gerechnet, dass sie es fertig bringen, den Splitterholzposten zu belagern...\n\nEs wird Zeit, dass sie dafür bezahlen!\n\nIn der Nähe, im Grabhügel von Dor'Danil, liegt etwas, das dem Feind äußerst teuer ist – das Herz des Waldes.\n\nIch brauche jemanden, der sich bis zum Herzen durchschlägt und es verderbt.\n\nDieser jemand seid Ihr, {name}.\n\nDoch zunächst bringt meine Axt zu Durak hier in den Minen. Er wird mit dem Blut unserer Feinde etwas anzufangen wissen.", sourceObjective = "Kadrak will, dass Ihr die blutbesudelte Axt zu Durak im Splitterholzposten bringt.\n\nBereitgestellter Gegenstand:", completion = "Das Herz des Waldes verderben?\n\nWie skrupellos – ein äußerst heimtückischer Schlag...\n\nDas gefällt mir!", sourceObjectiveStatus = "unverified-source-field" }
quests[13804] = { id = 13804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man ein Fischding fängt", description = "Schaut Euch nur die Ergebnisse an! Welch einzigartige elektrochemische Zusammensetzung! Ah, aber ich nehme nicht an, dass <ein bescheidener/eine bescheidene:c> {class} wie Ihr die Magnitüde meiner Entdeckung verstehen würde. Ich brauche ein lebendes Exemplar.\n\nIch würde mir ja selbst eines besorgen, aber offensichtlich sind sie bissig.\n\nHier, ich habe diese Falle so konfiguriert, dass sie sich ihren einzigartigen Hirnströmen anpasst. Stellt einfach die Falle auf und drückt diese Taste, um einen Sabberzahn einzusaugen. Doch zuerst müsst Ihr diesen Haftungsausschluss unterzeichnen. Diese Technologie ist das Neuste vom Neuen!", sourceObjective = "Stellt die Falle auf und benutzt die Fernbedienung, um einen lebenden Sabberzahnmurloc zu fangen. Bringt die gefüllte Falle zu Professor Flozz zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[13805] = { id = 13805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mitten ins Herz!", description = "So...\n\nDas Blut der gefallenen Kaldorei hat sich gewandelt. Es kann jetzt auf das Herz des Waldes im Grabhügel von Dor'Danil angewandt werden. Dadurch wird es gänzlich verderbt werden.\n\nDas heilige Relikt der hochmütigen Elfen wird gegen sie gerichtet. Das ist die Ironie des Lebens!\n\n<Durak lacht gehässig.>\n\nDer Grabhügel schmiegt sich in die Hügel im Südosten. Einer meiner Wichtel hat eine Blutspur gelegt, die vom Eingang bis zum Herzen führt.\n\nEilt Euch! Kadrak ist wahrscheinlich nicht besonders geduldig.\n\nFort mit Euch, {class}.", sourceObjective = "Durak will, dass Ihr das besudelte Blut der Kaldorei auf das Herz des Waldes anwendet.", completion = "Ist es vollbracht?\n\nGute Arbeit, {name}! Das wird ihre Streitkräfte langsam schwächen und auch ihren Geist.", sourceObjectiveStatus = "unverified-source-field" }
quests[13806] = { id = 13806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonendienst", description = "Höret, {class}, ich weiß, dass dieser Angriff auf den Splitterholzposten uns alle mitgenommen hat, aber falls wir die Satyrportale aus den Augen verlieren, steht uns nach dieser Krise eine noch größere bevor.\n\n<Locke starrt Euch ausdruckslos an.>\n\nIhr wisst nichts von den Portalen?\n\nIm Nordosten in der Region von Satyrnaar und Xavian unternehmen die Satyrn den Versuch, Dämonen zu beschwören, um ihre Zahl zu stärken.\n\nWir müssen diese Portale schließen, egal was sich uns dort auch in den Weg stellen mag.", sourceObjective = "Locke Okarr im Splitterholzposten will, dass Ihr 12 Satyrportale in Satyrnaar und Xavian schließt.", completion = "Gute Arbeit, {race}!\n\nEine Sache weniger, um die wir uns sorgen müssen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13807] = { id = 13807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kennzeichnung: Turniereinladung" }
quests[13808] = { id = 13808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In geheimer Mission", description = "Ich habe eine besondere Aufgabe. Für sie brauche ich einen gut ausgerüsteten, sachkundigen Helfer. Da ich niemanden sonst erübrigen kann, muss ich mich wohl mit Euch begnügen...\n\nDer Feind hat das Holzfällerlager des Kriegshymnenklans angegriffen und vom Rest unserer Streitkräfte abgeschnitten. Eine wichtige Diplomatin der Blutelfen, die auf dem Weg nach Orgrimmar war, wird dort gefangen gehalten.\n\nSie muss befreit werden.\n\nNehmt die Straße nach Nordosten und entzündet die schwelende Kohlenpfanne, um unseren Geheimagenten dorthin zu rufen. Tut, was immer er von Euch verlangt.\n\nWegtreten!", sourceObjective = "Kadrak will, dass Ihr die schwelende Kohlenpfanne gegenüber von Satyrnaar entzündet.", completion = "Es gibt für Euch hier alle Hände voll zu tun.\n\nHoffen wir, dass Ihr dieser Aufgabe gewachsen seid...", sourceObjectiveStatus = "unverified-source-field" }
quests[13809] = { id = 13809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohung von oben", description = "Hochlord Tirion Fordring hat die Wachen verdoppelt, seitdem Ihr den Spitzel des Kults der Verdammten entlarvt habt. Seiner Meinung nach werden sie nicht aufhören, nur weil ihr Schwarzer Ritter besiegt wurde.\n\nUnsere Späher der Himmelsklauen haben davon berichtet, einen Frostwyrm namens Frostschlund gesichtet zu haben, der einen Stoßtrupp des Kults anführen soll. Wenn wir sie nicht abfangen, werden sie das Turnier angreifen. Laut den Berichten der Späher fliegt Frostschlund gen Südwesten und patrouilliert das Gebiet zwischen dem Eisenwallbollwerk und Aldur'thar.", sourceObjective = "Eadric der Reine beim Argentumturnierplatz möchte, dass Ihr Frostschlund und 3 Kultistenbombenschützen besiegt.", completion = "{name}, Ihr und Eure Verbündeten habt das Turnier vor einem vernichtenden Angriff bewahrt. Unsere Himmelsklauenreiter mögen zwar tapfer sein, haben jedoch alle Hände voll damit zu tun, den Frieden auf dem Turnierplatz zu wahren, und sie hätten Mühe damit, den Luftraum gegen die Angriffe des Kults zu verteidigen. Euch gehört der Dank des Argentumkreuzzugs und all derjenigen, die sich hier versammelt haben, um am Wettkampf teilzunehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13810] = { id = 13810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht zum Gegner tragen", description = "Das Kolosseum befindet sich im gefährlichsten Teil der Welt, {name}. Blut und Qualen waren der Preis, den wir bezahlen mussten, um dieses Gebiet der Geißel abzunehmen; trotzdem schlägt unser Gegner mit einer scheinbar unerschöpflichen Armee weiterhin zurück. Und was die Sache noch schlimmer macht, ist, dass diese untote Armee von sterblichen Sympathisanten unterstützt wird - dem Kult der Verdammten.\n\nGeht nach Eiskrone und tötet jeden Kultisten, der Euch in die Quere kommt.", sourceObjective = "Cellian Tagesanbruch beim Argentumturnierplatz möchte, dass Ihr 15 Anhänger des Kults der Verdammten tötet. Dazu zählen alle Kultisten im Bereich von Eiskrone.", completion = "Ihr seid ein wahrer Champion, {name}, im Ring und auf dem Schlachtfeld. Wir alle müssen wachsam gegenüber der Geißel sein und Ihr seid unseren Brüdern und Eurem eigenen Volke ein Beispiel.", sourceObjectiveStatus = "unverified-source-field" }
quests[13811] = { id = 13811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter Champions", description = "Als Champion habt Ihr die Kunst des berittenen Kampfes zur Vollendung gebracht, habt Herausforderer aller Klassen bezwungen. Ihr müsst Euch sicher sein, dass Ihr jeden besiegen könnt, dem Ihr auf dem Turnier entgegentreten werdet.\n\nIhr solltet weiterhin an Euren eigenen Fertigkeiten feilen und von Euren Gegnern lernen. Champions aller Städte üben im Ring der Champions. Nehmt Eure Lanze, steigt auf irgendeins der angebundenen Reittiere, die Euch am Silberbundpavillon zur Verfügung stehen, und fordert sie heraus.", sourceObjective = "Bringt 4 Male des Champions zu Luuri beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.", progress = "Habt Ihr Euer Training mit den anderen Champions beendet?", completion = "Gut gemacht. Mit den anderen Champions zu trainieren ist einer der besten Wege, Euch auf den Turnierwettkampf vorzubereiten. Ich weiß, dass Ihr die Horde stolz machen werdet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13812] = { id = 13812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohung von oben", description = "Der Argentumkreuzzug hat die Wachen verdoppelt, seitdem Ihr den Spitzel des Kults der Verdammten entlarvt habt. Man weiß dort, dass die Kultisten nicht eher haltmachen werden, bis dieser Ort hier vernichtet und verhindert wurde, dass das Turnier stattfindet.\n\nDie Kundschafter des Argentumkreuzzugs haben davon berichtet, einen Frostwyrm namens Frostschlund gesichtet zu haben, der einen Stoßtrupp des Kults anführen soll.\n\nIhr müsst sie abfangen und beseitigen, bevor sie angreifen. Laut den Berichten der Späher fliegt Frostschlund gen Südwesten im Gebiet zwischen dem Eisenwallbollwerk und Aldur'thar herum.", sourceObjective = "Crok Geißelbann beim Argentumturnierplatz möchte, dass Ihr Frostschlund und 3 Kultistenbombenschützen besiegt.", completion = "{name}, Ihr habt das Turnier vor einem vernichtenden Angriff bewahrt. Der Argentumkreuzzug und all jene, die hier versammelt sind, stehen in Eurer Schuld und wir werden dafür sorgen, dass sie sich auch daran erinnern. Die Friedensbewahrer und Himmelsklauen machen so einen Wind darum, Schutz zu bieten, doch sie verbringen mehr Zeit damit, Schlägereien zwischen Betrunkenen aufzulösen, als uns vor der Geißel zu beschützen.\n\nMacht nichts - wir beschützen immer die unseren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13813] = { id = 13813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht zum Gegner tragen", description = "Es wird gut tun, bei all unseren Scheinkämpfen nicht zu vergessen, dass wir vom wahren Feind umgeben werden. Der Argentumkreuzzug möchte über einen Wettbewerb die besten Kämpfer ausfindig machen, doch das wäre schon mit denjenigen getan, die von der Schlacht zurückkehren. Lasst uns den Paladinen zeigen, dass wir willens sind, die Schlacht zum Kult der Verdammten zu tragen, selbst während wir uns auf das Turnier vorbereiten.\n\nGeht nach Eiskrone und tötet jeden Kultisten, dem Ihr begegnet. Sie sind besonders stark um Aldur'thar und Todessprechers Wacht vertreten.", sourceObjective = "Zor'be der Blutvergießer beim Argentumturnierplatz möchte, dass Ihr 15 Anhänger des Kults der Verdammten tötet. Dazu zählen alle Kultisten im Bereich von Eiskrone.", completion = "Ihr habt gute Arbeit dabei geleistet zu zeigen, dass wir unserer Verpflichtung nachkommen und die Geißel bekämpfen, egal wo wir sind oder was wir tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[13814] = { id = 13814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter Champions", description = "Als Champion habt Ihr die Kunst des berittenen Kampfes zur Vollendung gebracht, habt Herausforderer aller Klassen bezwungen. Ihr müsst Euch sicher sein, dass Ihr jeden besiegen könnt, dem Ihr auf dem Turnier entgegentreten werdet.\n\nIhr solltet weiterhin an Euren eigenen Fertigkeiten feilen und mehr über die Schwächen Eurer Gegner erfahren. Champions aller Städte üben im Ring der Champions in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon. Geht dorthin, nehmt Eure Lanze, wählt Euch irgendein zur Verfügung stehendes aus und fordert die Champions zu Übungskämpfen heraus.", sourceObjective = "Bringt 4 Male des Champions zu Illyrie Nachtlauer beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.", progress = "Habt Ihr Euer Training mit den anderen Champions beendet?", completion = "Ihr beherrscht den Umgang mit Eurem Reittier gut, {name}. Mit der Zeit werden Eure Gegner Euch fürchten lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13815] = { id = 13815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stümpfe machen", description = "Wie Euch bereits mitgeteilt wurde, sollen wir eine Diplomatin aus dem belagerten Holzfällerlager in Sicherheit bringen.\n\nSo wie es aussieht, ist das einfach unmöglich. Die Elfen halten tausend Pfeile auf die Ausgänge des Holzfällerlagers gerichtet.\n\nZunächst müssen wir ein Ablenkungsmanöver inszenieren – etwas, durch das sie ihren Blick eine Zeitlang vom Holzfällerlager abwenden.\n\nMeine Idee ist einfach. Nehmt diese Axt und fällt die Bäume, die sie in dieser Region pflegen.\n\nWenn Ihr damit fertig seid, entzündet die Kohlenpfanne hier, um wieder mit mir zu sprechen.", sourceObjective = "Krokk will, dass Ihr mit der Splitterholzaxt die Eichen des Eschentals im Holzfällerlager des Kriegshymnenklans fällt.", completion = "Gute Arbeit, {name}!\n\nIhr habt die Feinde demoralisiert und Ressourcen für die Horde gesammelt.\n\nHoffen wir, dass der Rest der Mission ebenso gut verläuft.", sourceObjectiveStatus = "unverified-source-field" }
quests[13816] = { id = 13816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroisch: Das Himmlische Planetarium", description = "Hört mal, <Kumpel/Mädel>! Das Schicksal von Azeroth steht hier auf dem Spiel.\n\nUnsere einzige Chance ist es, rechtzeitig das Himmlische Planetarium zu erreichen, um diesen Algalon zu finden und ihn davon abzuhalten, irgendwelche Nachrichten an seine titanischen Herren abzusetzen.\n\nFindet das Himmlische Planetarium und beschafft so viele Informationen wie möglich. Uns könnte noch immer ein wenig Zeit bleiben, uns auf Algalons Ankunft vorzubereiten.", sourceObjective = "Ausgrabungsleiterin Loren im Archivum in Ulduar möchte, dass Ihr den Eingang zum Himmlischen Planetarium findet.", completion = "Verschlossen? Das war ja klar!\n\nIch werde Brann Bescheid sagen... vielleicht kann er etwas im Archivum entdecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[13817] = { id = 13817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroisch: Datenscheibe des Archivums", description = "Diese Platinscheibe ist überraschend symmetrisch und frei von jedweden Kratzern und Unebenheiten. An ihrer Seite steht in auffallenden Runen eingeprägt das Wort \"ARCHIVUM\".\n\nIn Ulduar muss es eine Vorrichtung geben, mit welcher sich die Informationen auf der Scheibe lesen lassen.", sourceObjective = "Bringt die Datenscheibe des Archivums zur Archivumkonsole in Ulduar.", progress = "Die Konsole surrt vor Energie, als sich der runde Aufnahmebehälter öffnet.", completion = "Die Platinscheibe passt perfekt in die Konsole. Sie fängt an, sich zu drehen. Weiße Lichtstrahlen scheinen die darauf befindlichen Informationen abzutasten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13818] = { id = 13818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroisch: Algalon", description = "Ihr habt es wirklich geschafft, {name}. Bringt die Siegel zur Archivumkonsole und seht zu, ob Ihr Zugang zum Himmlischen Planetarium erhaltet.\n\nIhr beeilt Euch besser, <Kumpel/Mädchen>. Die Zeit drängt.", sourceObjective = "Bringt die Siegel der Wächter zur Archivumkonsole in Ulduar.", progress = "Die gleißenden Lichter der Konsole scannen mehrmals die Glasoberfläche, gerade so, als ob eine Form von Datenübermittlung erwartet würde.", completion = "Verifizierungsprozess läuft.\n\nZugang zum Himmlischen Planetarium gewährt. Bitte Schlüssel entnehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13819] = { id = 13819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroisch: Ende gut, alles gut", description = "Wir sollten uns jetzt besser beeilen, {name}. Wir müssen den Antwortcode von Dalaran aus übermitteln.\n\nBringt ihn zu Rhonin. Ich treffe Euch dort.", sourceObjective = "Überbringt Rhonin in Dalaran den Antwortcode Alpha.", progress = "Seid Ihr so weit, {name}?", completion = "Ihr seid hier. Lasst uns hoffen, dass das hier klappt. Um unser aller willen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13820] = { id = 13820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gebrüder Sprengbolz", description = "Der Hochlord hat mich damit beauftragt, das Kolosseum so schnell wie möglich fertig zu stellen. Wir haben unsere Bauarbeiter an das Projekt gesetzt, aber wir mussten sehr schnell feststellen, dass wir Hilfe bei der Beschaffung von Materialien brauchten. Ich habe ein paar Goblins angeheuert, Stumpi Sprengbolz und seinen Bruder Stümpi.\n\nSie beaufsichtigen die Arbeiten am südöstlichen Ende des Turniergeländes. Sprecht mit Stumpi und findet heraus, ob er und sein Bruder noch weitere Hilfe dabei brauchen, das benötigte Baumaterial zu beschaffen.", sourceObjective = "Sprecht mit Stumpi Sprengbolz am Argentumturnierplatz.", sourceObjectiveStatus = "unverified-source-field" }
quests[13821] = { id = 13821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroisch: Freyas Siegel", description = "Ich fürchte, Freyas Siegel zu erlangen, wird eine der schwierigeren Aufgaben sein.\n\nLaut dem Archivum ist die Essenz des Siegels mit ihren drei Dienern verbunden, den Ältesten Hellblatt, Eisenast und Steinrinde. Sollte einer der Ältesten zu Schaden kommen, ist die Unversehrtheit des Siegels gefährdet.\n\nDie Ältesten zu verschonen bedeutet jedoch, dass Freya mehr Macht haben wird, wenn Ihr Euch ihr stellen werdet.\n\nWas soll ich sagen, {name}, das ist eine ganz schöne Zwickmühle, in der wir da stecken.", sourceObjective = "Ausgrabungsleiterin Loren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Freyas Siegel gelangt.\n\nUm mehr darüber herauszufinden, wie Ihr Freyas Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.", progress = "Freyas Siegel, {name}? Habt Ihr es?", completion = "Verdammt gute Arbeit, {name}. Wir sind unserem Ziel, Azeroth zu retten, einen Schritt näher!", sourceObjectiveStatus = "unverified-source-field" }
quests[13822] = { id = 13822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroisch: Hodirs Siegel", description = "Es wird nicht einfach sein, Hodirs Siegel zu beschaffen. Ihr müsst nämlich nicht nur Hodir selbst vernichten, sondern es auch noch tun, bevor er die Truhe zerstört, in der es sich befindet!\n\nSchaut Euch die Archivumkonsole an, falls Ihr weitere Informationen benötigt. Das Ding umfasst mehr Wissen als alle Bibliotheken der Welt zusammen!", sourceObjective = "Ausgrabungsleiterin Loren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Hodirs Siegel gelangt.\n\nUm mehr darüber herauszufinden, wie Ihr Hodirs Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.", progress = "Konntet Ihr das Siegel bekommen, {name}?", completion = "Ihr habt es geschafft! Ich weiß nicht wie, aber Ihr habt es geschafft!", sourceObjectiveStatus = "unverified-source-field" }
quests[13823] = { id = 13823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroisch: Thorims Siegel", description = "Thorim ist nicht er selbst, {name}. Er ist das Opfer einer dunklen Macht geworden, die ihn nun steuert.\n\nDas Opfer von etwas Bösem, das ihm die Illusion vorspielt, seine verstorbene Frau Sif zu sein.\n\nIhr dürft nicht zulassen, dass der Zauber dieses Betrügers ihn überwältigt. Denn sollte es so kommen, wird das Wissen um die Lage des Siegels für immer verloren sein!\n\nIhr müsst ihn zur Vernunft bringen und zwar schnell.\n\nWie immer wird Euch die Archivumkonsole mit allen schmutzigen Details versorgen... selbst mit denen, die Euch nicht gefallen.", sourceObjective = "Ausgrabungsleiterin Loren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Thorims Siegel gelangt.\n\nUm mehr darüber herauszufinden, wie Ihr Thorims Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.", progress = "Nun, {name}? Habt Ihr's?", completion = "Ihr werdet wohl nie aufhören, mich zu beeindrucken, {name}.\n\nIhr und ich sollten mal ein Bierchen trinken gehen, nachdem wir mit all dem hier durch sind. Mein Wort drauf!", sourceObjectiveStatus = "unverified-source-field" }
quests[13824] = { id = 13824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroisch: Mimirons Siegel", description = "Mimiron ist ein ganz Schlauer. Sein gesamter Sitz ist mit einer Art Selbstzerstörungsmechanismus ausgestattet.\n\nUnglücklicherweise wird es ein Wettlauf gegen die Zeit werden, um sein Siegel zu bekommen. Befragt die Archivumkonsole, um Näheres darüber zu erfahren, falls nötig.", sourceObjective = "Ausgrabungsleiter Doren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Mimirons Siegel gelangt.\n\nUm mehr darüber herauszufinden, wie Ihr Mimirons Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.", progress = "Konntet Ihr das Siegel an Euch bringen, {name}?", completion = "Das muss man Euch wirklich lassen, {name}. Unsere Chancen stehen vielleicht nicht zum Besten, aber wenn Ihr mit anpackt fühle ich mich gleich viel besser.", sourceObjectiveStatus = "unverified-source-field" }
quests[13825] = { id = 13825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muschelette Surprise", sourceObjective = "Hey, ich erinnere mich an Euch! Seid Ihr nicht {name}? Ihr habt mir doch mal geholfen, das ganze Muschelette zu machen!\n\nIch sag Euch was: Kommt näher und ich zeige Euch mein neustes Rezept - es ist einfach und köstlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[13826] = { id = 13826, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nat Pagle, Extremangler" }
quests[13827] = { id = 13827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz!" }
quests[13828] = { id = 13828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Nahkampf beherrschen", description = "Der Mittelpunkt des Turnierwettkampfes ist der berittene Nahkampf. Nehmt diese Lanze und steigt auf das Streitross der Quel'dorei, das gleich außerhalb des Pavillons abgestellt ist.\n\nSprecht mit Jeran Waldesruh, sobald Ihr erst einmal im Sattel sitzt. Er befindet sich am nördlichen Rand des Turnierplatzes im Trainingsbereich östlich des Rings der Streiter. Jeran wird Euch beibringen, wie man sich im Nahkampf verteidigen kann.", sourceObjective = "Nehmt Eure Lanze und steigt auf das abgestellte Streitross der Quel'dorei außerhalb des Pavillons. Sprecht mit Jeran Waldesruh und wendet fünfmal die Fähigkeit 'Zustoßen' gegen ein Nahkampfziel an. Kehrt anschließend zu Arkanist Taelis beim Argentumturnierplatz zurück.", completion = "Behaltet die Worte des Meisters im Kopf, während Ihr mit den Trainingsattrappen trainiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[13829] = { id = 13829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Nahkampf beherrschen", description = "Der Mittelpunkt des Turnierwettkampfes ist der berittene Nahkampf. Nehmt diese Lanze und steigt auf den Falkenschreiter der Sonnenhäscher, der gleich außerhalb des Pavillons abgestellt ist.\n\nSprecht mit Jeran Waldesruh, sobald Ihr erst einmal im Sattel sitzt. Er befindet sich am nördlichen Rand des Turnierplatzes im Trainingsbereich östlich des Rings der Streiter. Jeran wird Euch beibringen, wie man sich im Nahkampf verteidigen kann.", sourceObjective = "Nehmt Eure Lanze und steigt auf den abgestellten Falkenschreiter der Sonnenhäscher außerhalb des Pavillons. Sprecht mit Jeran Waldesruh und wendet fünfmal die Fähigkeit 'Zustoßen' auf ein Nahkampfziel an. Kehrt anschließend zu Magister Edien Sonnental beim Argentumturnierplatz zurück.", completion = "Behaltet die Worte des Meisters im Kopf, während Ihr mit den Trainingsattrappen trainiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[13830] = { id = 13830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geisterfisch", description = "Jeder Angler in Nordend, der sein Geld wert ist, weiß über den Pygmäenschiffshalter Bescheid. Er ist nicht essbar, manchmal jedoch für Alchemisten nützlich.\n\nEs gibt jedoch einen Fisch, einen etwas verstohleneren, der sich zwischen den Schiffshaltern im Flussnabel im Sholazarbecken versteckt: der Phantomgeisterfisch. Außerhalb des Wassers werden sie zunehmend lichtdurchlässig, bis sie schließlich ganz verschwinden. Einige nehmen an, dass sie nach Sholazar zurückkehren, andere wiederum sind etwas... abergläubischer.\n\nIch möchte, dass Ihr diesen Fisch fangt und um jeden Preis hinter sein Geheimnis kommt!", sourceObjective = "Marcia Balzer in Dalaran möchte, dass Ihr hinter das Geheimnis des Phantomgeisterfischs kommt.", completion = "Man wird also unsichtbar, wenn man ihn isst... was für eine seltsame Verteidigung dieser Fisch doch entwickelt hat.\n\nIch brauch ein Weilchen, um das zu verdauen - Wortspiel nicht beabsichtigt, {name}; wirklich. Wieso kommt Ihr nicht morgen wieder?", sourceObjectiveStatus = "unverified-source-field" }
quests[13831] = { id = 13831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besorgniserregende Rezepte", description = "Hier steht eine einfache, hastig zusammengezimmerte Werkbank eines Apothekers, die unter der Last gekritzelter Notizen und giftigem Gebräu fast zusammenbricht. Es sieht so aus, als hätten die Verlassenen auch Faulhufs Handwerk untersucht. Ihr schnappt Euch die Notiz, die am wichtigsten aussieht und bereitet Euch darauf vor, alles zu zerstören, bevor Ihr dem Baumwahrer von Eurer Entdeckung berichtet.", sourceObjective = "Bringt die Notizen des Apothekers zu Tharnariun Baumwahrer in Lor'danel.", progress = "Was ist das? Habt Ihr noch etwas in der Höhle gefunden?", completion = "<Tharnariun Baumwahrer durchblättert die Notizen, während Ihr Euren Bericht abliefert, sein Gesicht verfinstert sich sorgenvoll.>\n\nDie Verlassenen interessieren sich für die Arbeit von Faulhuf? Mir dreht sich der Magen um, wenn ich daran denke, was sie mit seiner Verderbnis alles anrichten könnten. Ihr habt gut daran getan, die Arbeit zu zerstören, aber die Notizen beunruhigen mich sehr. Was haben die Verlassenen hier zu suchen? Arbeiten sie mit den Splitterspeertrollen im Norden zusammen? Sorgen über Sorgen, {class}. Ich bin froh, dass Ihr hier seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[13832] = { id = 13832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perle der Kanalisation", description = "Schwer zu glauben, dass die meisten Leute, wenn sie zum Angeln in die Kanalisation von Dalaran gehen, nach Riesenratten und mutierten Fischen suchen. Besonders dann, wenn im Wasser Unmengen unbezahlbarer Juwelen zu finden sind - von gebrochenen Herzen, Dieben und achtlosen Trunkenbolden weggeworfen.\n\nDer Trick bei der Sache ist, Euren Haken am Boden entlang zu ziehen, und wenn Ihr etwas gefunden habt, beim Hochziehen nicht zu viel Kraft zu verwenden. Versucht es einmal, {name}. Ich wäre dazu bereit, was auch immer Ihr findet gegen ein paar meiner eigenen Schmuckstücke einzutauschen.", sourceObjective = "Marcia Balzer in Dalaran möchte, dass Ihr ihr korrodierten Schmuck bringt.", progress = "Hattet Ihr Glück?", completion = "Also, das sieht aus, als könnte es wertvoll sein. Schwer zu sagen, bis es gesäubert und geschätzt wurde, aber ich bin noch immer dazu bereit, den Handel einzugehen, wenn Ihr es auch seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[13833] = { id = 13833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut ist dicker", description = "Der Blutzahnfrenzy ist ein quirliger kleiner Fisch, der für ein Rezept zur Heilung von infizierten Wunden verwendet wird. Wir könnten ein paar von ihnen gebrauchen, wenn Ihr helfen wollt.\n\nWie der Name schon sagt, trinken sie gerne Blut. Die einzige mir bekannte Art und Weise, die kleinen Teufel zu fangen, ist, Blut ins Wasser zu schütten und dann darin zu angeln.\n\nBeschmiert Euch also mit Blut... Tötet dazu einfach eine der Bestien in der Boreanischen Tundra und springt anschließend ins Wasser. Ihr werdet im Nu den perfekten Köder haben.", sourceObjective = "Marcia Balzer in Dalaran möchte, dass Ihr ihr 5 Blutzahnfrenzys bringt.", progress = "Irgendwelches Glück mit den Blutzahnfrenzys gehabt? Vergesst nicht, was ich Euch über das Blut gesagt habe.", completion = "Ihr seid mutig, {name}. Hoffe, dass Ihr beim Vorbereiten Eures Angelplatzes keine Gliedmaßen verloren habt. Wenn Ihr noch immer wild aufs Fischen seid, dann kommt morgen wieder und wir werden uns mehr darüber unterhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13834] = { id = 13834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefährlich köstlich", description = "Die besten Angelplätze sind oft die gefährlichsten. Für diejenigen, die dreist genug sind, bietet sich Tausendwinter an - dort sind großzügige Fänge zu machen.\n\nGenau genommen ist es der einzige Ort, wo man den sagenhaften Schreckensfisch fangen kann - ein Fisch, tödlich und köstlich zugleich. Bringt mir ein paar und wir können weiterreden.", sourceObjective = "Marcia Balzer in Dalaran möchte, dass Ihr ihr 10 Schreckensfische bringt.", progress = "Seid auf der Hut, wenn Ihr hinter dem Schreckensfisch her seid.", completion = "Du meine Güte! Ihr habt Euch ein paar Schreckensfische gefangen. Das erinnert mich an die Zeit, als...\n\n<Marcia erinnert sich an Geschichten von Abenteuer und Fischfang und wird sie so lange erzählen, wie Ihr nur zuhören wollt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[13835] = { id = 13835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Schildbrecherangriff beherrschen", description = "Ihr werdet lernen müssen, wie man die Verteidigung Eures Gegners durchbrechen kann, um im berittenen Kampf erfolgreich zu sein. Nehmt diese Lanze und steigt auf das angebundene Streitross der Quel'dorei gleich außerhalb des Pavillons.\n\nSprecht mit Valis Windhetzer, sobald Ihr erst einmal im Sattel sitzt. Er befindet sich am nördlichen Rand des Turnierplatzes im Trainingsbereich östlich des Rings der Streiter. Valis wird Euch die Grundlagen des Schildbrecherangriffs beibringen und wie man mit ihm ein Distanzziel verwundbar macht.", sourceObjective = "Nehmt Eure Lanze und steigt auf das abgestellte Streitross der Quel'dorei außerhalb des Pavillons. Sprecht mit Valis Windhetzer und wendet die Fähigkeit \"Schildbrecher\" gegen 2 ungeschützte Distanzziele an. Kehrt anschließend zu Späherin Shalyndria beim Argentumturnierplatz zurück.", completion = "Prägt Euch Valis' Lektionen ein, {name}. Es wird den Unterschied zwischen Sieg und Niederlage Eurer berittenen Kämpfe bedeuten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13836] = { id = 13836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arm dran, Arm ab!", description = "Ich habe von einem tragischen Zwischenfall im Gefängnis von Dalaran gehört; ein besonders brutaler Insasse hat einer Wache einen Arm abgerissen und ihn ins Wasser geworfen. Die Leute von der \"Ersten Hilfe\"-Station haben versprochen, dass sie den Arm wieder annähen können, falls wir ihn zurückbringen.\n\nIhr angelt einfach lange genug im Wasser vor der Violetten Festung, und ich verwette meine Lieblingsangelrute darauf, dass der Arm auftaucht. Findet ihn und bringt ihn zu Olisarra der Gütigen hier in Dalaran. Sie wird wissen, was zu tun ist.", sourceObjective = "Olisarra die Gütige in Dalaran möchte, dass Ihr ihr den abgetrennten Arm bringt.", progress = "Seid gegrüßt. Habt Ihr etwas für mich?", completion = "Oh, seid gegrüßt, {name}. Marcia hat gesagt, dass Ihr den fehlenden Arm des armen Kerls vorbeibringen würdet.\n\nAußerdem hat sie mir diese Tasche hier dagelassen, um sie Euch als Belohnung zu geben. Sie riecht scheußlich und ich kann es kaum erwarten, den Handel abzuschließen, falls Ihr nichts dagegen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13837] = { id = 13837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Ansturmangriff beherrschen", description = "Euer stärkster Angriff im berittenen Kampf ist zweifellos 'Sturmangriff'. Nehmt diese Lanze und steigt auf das Streitross der Quel'dorei, das gleich außerhalb des Pavillons abgestellt ist.\n\nSprecht mit Rugan Stahlbauch, sobald Ihr erst einmal im Sattel sitzt. Er befindet sich am nördlichen Rand des Turnierplatzes im Trainingsbereich östlich des Rings der Streiter. Rugan wird Euch sagen, wie diese mächtige Fähigkeit zu verwenden ist und Euch ein paar grundlegende Strategien beibringen.", sourceObjective = "Nehmt Eure Lanze und steigt auf das abgestellte Streitross der Quel'dorei außerhalb des Pavillons. Sprecht mit Rugan Stahlbauch und wendet die Fähigkeit 'Sturmangriff' gegen 2 ungeschützte Sturmangriffsziele an. Kehrt anschließend zu Avareth Flinkstoß beim Argentumturnierplatz zurück.", progress = "Beherrscht Ihr nun 'Sturmangriff'?", completion = "Mit etwas Erfahrung und Übung wird Euer Ansturm tödlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13838] = { id = 13838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Schildbrecherangriff beherrschen", description = "Ihr werdet lernen müssen, wie man durch die Verteidigung Eures Gegners brechen kann, um im berittenen Kampf erfolgreich zu sein. Nehmt diese Lanze und steigt auf den abgestellten Falkenschreiter der Sonnenhäscher gleich außerhalb des Pavillons.\n\nSprecht mit Valis Windhetzer, sobald Ihr erst einmal im Sattel sitzt. Er befindet sich am nördlichen Rand des Turnierplatzes im Trainingsbereich östlich des Rings der Streiter. Valis wird Euch die Grundlagen des Schildbrecherangriffs beibringen und wie man mit ihm ein Distanzziel verwundbar macht.", sourceObjective = "Nehmt Eure Lanze und steigt auf den abgestellten Falkenschreiter der Sonnenhäscher. Sprecht mit Valis Windhetzer und wendet die Fähigkeit 'Schildbrecher' gegen 2 ungeschützte Distanzziele an. Kehrt anschließend zu Galathia Morgenglanz beim Argentumturnierplatz zurück.", completion = "Prägt Euch Valis' Lektionen ein, {name}. Es wird den Unterschied zwischen Sieg und Niederlage Eurer berittenen Kämpfe bedeuten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13839] = { id = 13839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Ansturmangriff beherrschen", description = "Euer stärkster Angriff im berittenen Kampf ist zweifellos 'Sturmangriff'. Nehmt diese Lanze und steigt auf das Streitross der Quel'dorei, das gleich außerhalb des Pavillons abgestellt ist.\n\nSprecht mit Rugan Stahlbauch, sobald Ihr erst einmal im Sattel sitzt. Er befindet sich am nördlichen Rand des Turnierplatzes im Trainingsbereich östlich des Rings der Streiter. Rugan wird Euch sagen, wie diese mächtige Fähigkeit zu verwenden ist, und Euch ein paar grundlegende Strategien beibringen.", sourceObjective = "Nehmt Eure Lanze und steigt auf den angebundenen Falkenschreiter der Sonnenhäscher außerhalb des Pavillons. Sprecht mit Rugan Stahlbauch und wendet die Fähigkeit 'Sturmangriff' gegen 2 ungeschützte Sturmangriffsziele an. Kehrt anschließend zu Amariel Sonnenschwur beim Argentumturnierplatz zurück.", completion = "Mit etwas Erfahrung und Übung wird Euer Ansturm tödlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13840] = { id = 13840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE", description = "Gack... gack... gack... GAGGACK!\n\nGack... gack... gack.\n\nDas Huhn sieht zu Euch hinauf und beginnt dann, mit seinen Krallen am Boden zu scharren. Ihr glaubt, dass es ein Wort schreibt, aber Ihr seid Euch nicht sicher, was es ist. Könnte es das sein... S-A-L-D-E-A-N? Bevor Ihr fragen könnt, dreht sich das Huhn weg und kümmert sich um seine Angelegenheiten.", sourceObjective = "Beschafft Euch etwas Spezialhühnerfutter und kehrt zu dem Huhn zurück, das sich mit Euch angefreundet hat. Wenn Ihr es gefunden habt, dann benutzt erst /cheer, ehe Ihr dem Huhn das Spezialhühnerfutter gebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13841] = { id = 13841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit der Bitte um Entschuldigung", description = "Das könnte mein Ende bedeuten... Vielleicht sind meine Taten nicht so gut durchdacht gewesen, wie sie hätten sein sollen...\n\nDie gute Nachricht ist, dass wir einen Angriff zurückgeschlagen haben, der anderenfalls den Untergang des Splitterholzpostens zur Folge gehabt hätte. Lasst uns beten, dass Saurfang es genauso sieht.\n\nIch werde sicherlich nach Orgrimmar gerufen werden, um mich für meine Taten zu rechtfertigen.\n\nBitte, {name}, eilt mir voraus und überreicht seinem Berater Etrigg diesen Brief.\n\nTut was in Eurer Macht steht, um ihn mir gegenüber milde zu stimmen.", sourceObjective = "Draaka bittet Euch, Etrigg in Orgrimmar den Brief mit ihrer Erklärung zu bringen.\n\nBereitgestellter Gegenstand:", completion = "Diese Frau, Draaka, muss gut Acht geben. Sie spielt mit Kräften, die sie nicht beherrscht.\n\n<Etrigg mustert Euch einen Augenblick lang.>\n\nIch habe bei diesem Durak ein schlechtes Gefühl. Und auf meine Instinkte kann ich mich normalerweise verlassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13842] = { id = 13842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tod steht ihm gut", description = "Ich habe das Gefühl, dass mehr hinter diesem Durak steckt, als man auf den ersten Blick erkennt. Dämonische Kräfte sind gefährlich und ihre verderbende Wirkung kann auch erfahrenen Hexenmeistern zum Verhängnis werden.\n\nIch traue ihm nicht, {name}.\n\nIhr müsst diesen Durak finden und ihm mitteilen, dass die Horde nichts mit ihm zu tun haben will.", sourceObjective = "Sprecht mit Durak in den Splitterholzminen.", completion = "Wie ich es mir dachte, war er also eine Bedrohung. Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13843] = { id = 13843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Konstruktionsset: Schrottboter", description = "Ihr durchsucht die Datenbanken der Prototypenkonsole und findet dabei ein Schema für ein Schrottboterkonstruktionsset. Mit Eurer Ingenieursfertigkeit könntet Ihr lernen, Konstruktionssets wie dieses selbst herzustellen.Ihr erlernt:", sourceObjective = "Benutzt die Prototypenkonsole in der Bibliothek des Erfinders.", sourceObjectiveStatus = "unverified-source-field" }
quests[13844] = { id = 13844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Althalaxx plündern", description = "Bevor Ihr Euch gleich wieder in die Schlacht stürzt, möchte ich Euch über ein paar neue Entwicklungen in Kenntnis setzen, {class}. Meine Späher berichten mir, dass der Turm von Althalaxx im Süden von den Verlassenen überrannt wird.\n\nVor dem Angriff war dieser trostlose Turm die Heimat eines fanatischen Zweigs des Schattenrats, der von dem gefallenen Hochgeborenen Athrikus Narassin angeführt wurde. Narassin ist längst tot, aber wir dürfen es nicht ignorieren, falls etwas von seinem Werk weiterbesteht. Beschafft Euch seine Forschung und tötet den Kommandanten der Verlassenen, der die Ruinen plündert.", sourceObjective = "Findet Narassins Foliant in den Ruinen von Althalaxx und tötet Teegan Holloway, den Kommandanten der Verlassenen.", progress = "Narassin selbst bereitet uns keinen Ärger mehr, aber wenn sein Lebenswerk in die falschen Hände gerät, könnte sich das dunkle Wissen jahrzehntelanger Studien über unseren Köpfen zusammenbrauen. Habt Ihr etwas finden können?", completion = "Mal sehen, was wir hier haben... Bei Elune, seine Notizen allein schon sind in einem halben Dutzend Sprachen geschrieben. Und ist das Blut? Dieses Archiv lässt mich erschauern, aber immerhin sind wir in Sicherheit. Es wird dauern, bis wir alle Notizen entziffern können.\n\nOh, Eure Belohnung? Ja, hier. Eine nette Abwechslung, mal nicht mit untoten Dieben zu arbeiten. Jetzt zurück in den Kampf mit Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[13845] = { id = 13845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versiegelte Giftphiole", description = "Diese Giftphiole sieht besonders gefährlich aus. Womöglich könnte jemand in Dalaran daran interessiert sein.", sourceObjective = "Bringt die versiegelte Giftphiole zu Alchemist Cinesra in die Kanalisation von Dalaran.", progress = "Ist das, was ich denke, {class}?", completion = "Ihr seid mutig, das hier mit Euch herumgetragen zu haben. Wenn nur ein Tropfen auf Eure Haut gekommen wäre, hättet Ihr auf schmerzlichste Weise den Tod gefunden.\n\nErlaubt mir, Euch dafür zu entlohnen... Gift von außergewöhnlicher Stärke kann ich immer gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13846] = { id = 13846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Beitrag leisten", description = "Die besten der Champions kommen jeden Tag zur Kapelle, um der Argentumbeichtpatin zuzuhören.\n\nIhr solltet sehen, wie sehr sie von ihr inspiriert werden, {name}. Sie ziehen nicht nur für den Argentumkreuzzug in den Kampf, sondern geben auch noch sehr viel Geld in den Klingenbeutel, wenn ich ihn herumtrage.\n\nWollt Ihr womöglich auch einen Beitrag leisten?", sourceObjective = "Sprecht mit Knappe Artie, um einen Beitrag von 10 Gold an den Argentumkreuzzug zu leisten.", progress = "Wollt Ihr einen Beitrag leisten?", completion = "Habt Dank. Ich weiß einfach, dass es der Kreuzzug gut einsetzen wird!", sourceObjectiveStatus = "unverified-source-field" }
quests[13847] = { id = 13847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor den Toren des Feindes", description = "Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Hauptmann Joseph Holley beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.", completion = "Eure Tapferkeit auf dem Feld hat bestätigt, was die Kreuzfahrer ohnehin schon wussten: dass unsere Krieger mehr sind als bloße Dekoration für den Exerzierplatz.", sourceObjectiveStatus = "unverified-source-field" }
quests[13848] = { id = 13848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überbringer schlechter Nachrichten", description = "Seit Beginn der Belagerung des Splitterholzpostens hat es keine Nachricht nach dort draußen geschafft. Inzwischen muss Kommandant Grimmfang sich Sorgen machen.\n\nIch entsende Euch zum Zoramstrand, um unseren Bericht abzuliefern. Er enthält keine guten Nachrichten, aber zumindest erfährt er dann die Fakten.\n\nSprecht mit Vhulgra, wenn Ihr bereit zum Aufbruch seid.", sourceObjective = "Kadrak will, dass Ihr mit Kommandant Grimmfang am Zoramstrand sprecht.\n\nBereitgestellter Gegenstand:", completion = "<Kommandant Grimmfang runzelt die Stirn, als er den Bericht liest.>\n\nDas sind in der Tat schlechte Nachrichten.\n\nMögen die Geister sie beschützen, bis wir unseren Weg bis zum Splitterholzposten erkämpft haben...", sourceObjectiveStatus = "unverified-source-field" }
quests[13849] = { id = 13849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Astranaar brennt!", description = "{class}, Astranaar steht in Flammen!\n\nSchnell, nehmt diesen Wassereimer und löscht das Feuer, bevor nichts mehr übrig ist!", sourceObjective = "Löscht 15 Feuer.", completion = "Habt Dank!\n\nJetzt ist es an der Zeit, sich um die Horde zu kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[13850] = { id = 13850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gifttoleranz", description = "Ihr wollt eine Gifthaut reiten? Dann hab' ich schlechte Neuigkeiten für Euch.\n\nDie Gifthautravasaurier, die bestehen aus nichts als Gift: giftiges Blut, giftiger Speichel, giftige Haut. Ihr steigt auf einen drauf und fallt nach ein paar Stunden tot runter.\n\nIhr müsstet zuerst gegen ihre Gifte resistent werden, bevor ich Euch einen verkaufe, und das dauert ganz schön lange... Ihr müsstet mit ihrem giftigem Blut bespritzt werden, wenn Ihr sie bekämpft. Und zwar sehr oft. Wenn Ihr wirklich daran interessiert seid: Die Gifthäute bevorzugen die nördliche Gegend der Marschen nordwestlich von hier.", sourceObjective = "Mor'vek im Krater von Un'Goro behauptet, dass wenn man 20-mal von dem Blut eines Gifthautravasaurus vergiftet wurde, auf einem reiten könnte, ohne zu sterben. Greift die Saurier an, um vielleicht vergiftet zu werden.", completion = "Ihr habt es geschafft? Ihr habt es wirklich geschafft?!\n\nHo ho! Dickköpfig wie meine Frau seid Ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[13851] = { id = 13851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor den Toren des Feindes", description = "Während wir die Vorbereitungen für das Turnier treffen, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Clara Torkelbräu beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.", completion = "Eure Tapferkeit auf dem Feld hat den Kreuzfahrern gezeigt, dass wir würdige Verbündete sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[13852] = { id = 13852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor den Toren des Feindes", description = "Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Klick Radspanner beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.", completion = "Eure Tapferkeit hat gezeigt, dass wir den Anhängern des Argentumkreuzzugs ebenbürtig sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[13853] = { id = 13853, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Feuer erwidern", description = "Die meisten Feuer sind unter Kontrolle, aber wir müssen etwas gegen diese Windreiter unternehmen!\n\nSchnell, {name}, Ihr müsst in eine unserer Glevenschleudern klettern und das Feuer erwidern!", sourceObjective = "Verwendet eine Schleuder von Astranaar, um 15 von Höllschreis Vandalen und ihre Wachwindreiter abzuschießen.", completion = "Wir sind gerettet! Ihr habt genug abgeschossen. Den Rest sollten wir selbst erledigen können.\n\nIch kann Euch gar nicht genug danken, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13854] = { id = 13854, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor den Toren des Feindes", description = "Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Ranii beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.", completion = "Eure Tapferkeit auf dem Feld hat bestätigt, was die Kreuzfahrer ohnehin schon wussten: dass unsere Krieger mehr sind als bloße Dekoration für den Exerzierplatz.", sourceObjectiveStatus = "unverified-source-field" }
quests[13855] = { id = 13855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor den Toren des Feindes", description = "Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Airae Sternensucher beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.", completion = "Eure Tapferkeit auf dem Feld hat den Kreuzfahrern gezeigt, dass sie sich im Kampf gegen den Lichkönig auf uns verlassen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[13856] = { id = 13856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor den Toren des Feindes", description = "Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Morah Worgschwester beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.", completion = "Eure Tapferkeit auf dem Feld hat bestätigt, was die Kreuzfahrer ohnehin schon wussten: dass unsere Krieger die besten auf Azeroth sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[13857] = { id = 13857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor den Toren des Feindes", description = "Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Gahju beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.", completion = "Eure Tapferkeit auf dem Feld hat den Kreuzfahrern gezeigt, dass wir angesichts der Diener des Lichkönigs keine Angst kennen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13858] = { id = 13858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor den Toren des Feindes", description = "Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Anka Klauenhuf beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache un 3 Leutnants der Knochenwache vernichtet.", completion = "Eure Tapferkeit auf dem Feld hat den Kreuzfahrern gezeigt, dass wir loyale Verbündete im Kampf gegen den Lichkönig sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[13859] = { id = 13859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor den Toren des Feindes", description = "Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Aneera Thuron beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.", completion = "Eure Tapferkeit auf dem Feld hat den Kreuzfahrern gezeigt, dass wir bereit sind, jedem Gegner zu trotzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13860] = { id = 13860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor den Toren des Feindes", description = "Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Tierführer Dretch beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.", completion = "Der Argentumkreuzzug hat gesehen, wie entschlossen wir sind, und sie wissen, dass unsere Krieger die Sache zu Ende bringen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[13861] = { id = 13861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht vor der Zitadelle", description = "Während einige von uns auf dem Turnier alles geben, bereiten unsere Brüder den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross im Lager und vernichtet die Kommandanten des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Eadric der Reine beim Argentumturnierplatz möchte, dass Ihr 3 Kommandanten der Knochenwache tötet.", completion = "Es ermutigt uns vom Argentumkreuzzug, jemanden wie Euch zu haben, der Seite an Seite mit uns gegen den Lichkönig kämpft.", sourceObjectiveStatus = "unverified-source-field" }
quests[13862] = { id = 13862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht vor der Zitadelle", description = "Während einige von uns auf dem Turnier alles geben, bereiten unsere Brüder den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross im Lager und vernichtet die Kommandanten des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Eadric der Reine beim Argentumturnierplatz möchte, dass Ihr 3 Kommandanten der Knochenwache tötet.", completion = "Es ermutigt uns vom Argentumkreuzzug, jemanden wie Euch zu haben, der Seite an Seite mit uns gegen den Lichkönig kämpft.", sourceObjectiveStatus = "unverified-source-field" }
quests[13863] = { id = 13863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht vor der Zitadelle", description = "Während sich einige der Kreuzfahrer auf das Turnier vorbereiten, wurden andere ausgesandt, um die Hochburg des Feindes, die Eiskronenzitadelle, anzugreifen.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross im Lager und vernichtet die Kommandanten des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Crok Geißelbann beim Argentumturnierplatz möchte, dass Ihr 3 Kommandanten der Knochenwache tötet.", completion = "Wir sind nie vor der Geißel zurückgewichen, haben sie das Fürchten gelernt und diese Kampagne wird nicht anders sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13864] = { id = 13864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht vor der Zitadelle", description = "Während sich einige der Kreuzfahrer auf das Turnier vorbereiten, wurden andere ausgesandt, um die Hochburg des Feindes, die Eiskronenzitadelle, anzugreifen.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross im Lager und vernichtet die Kommandanten des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Crok Geißelbann beim Argentumturnierplatz möchte, dass Ihr 3 Kommandanten der Knochenwache tötet.", completion = "Wir haben die Geißel an allen Fronten bekämpft, haben sie das Fürchten gelernt und diese Kampagne wird nicht anders sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13865] = { id = 13865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drei Anführer sind drei zu viel", description = "Hört gut zu, {class}.\n\nIn dieser Region gibt es drei Kommandanten der Elfen, die ihre Bemühungen gezielt auf das Holzfällerlager richten. Sie zu töten, würde sicherlich Panik und ein Durcheinander anrichten. Hoffentlich ausreichend, sodass wir unsere Mission erfolgreich durchführen können.\n\nWo Ihr schon dabei seid: Die Vernichtung ihrer Späher kann unserer Sache nur dienlich sein.", sourceObjective = "Krokk will, dass Ihr Dorinar, Arminon, Endolar und 12 Eschentalspäher tötet.", completion = "Gute Arbeit, {class}.\n\nBei ihnen herrscht ein heilloses Durcheinander. Seht sie Euch an!", sourceObjectiveStatus = "unverified-source-field" }
quests[13866] = { id = 13866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Schutzwall!", description = "Diese Wälder mögen ruhig sein, aber unsere Feinde lauern hinter jedem Baum. Ich habe schon so manchen Orc mit Pfeilen in seinem Rücken entdeckt und die Waffe noch nicht gezückt.\n\nHier ist es tückisch hinter den feindlichen Linien, aber wir könnten starke Arme und kluge Köpfe dort unten im Schutzwall von Mor'shan gebrauchen. Kadrak bereitet eine Offensive von dort aus vor – er zieht Taten den Worten vor. Ihr werdet Euch gut mit ihm verstehen.\n\nSprecht mich wieder an, wenn Ihr bereit seid, und ich fliege Euch dorthin.", sourceObjective = "Sprecht mit Kulg Blutspritzer an der Grenze zwischen dem Eschental und Azshara, um zum Schutzwall von Mor'shan gebracht zu werden. Meldet Euch bei Kadrak, wenn Ihr dort eintrefft.", completion = "Ihr kommt genau zur rechten Zeit, {class}. Der alte Kulg schleicht schon zu lange durch diese Wälder. Er wird übervorsichtig und fürchtet sich vor jedem Schatten. Wir werden diesen Wald nicht länger fürchten – die Zeit ist gekommen, das Eschental ein für alle Mal zu unterwerfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13867] = { id = 13867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Eindämmung der Furbolgbedrohung", description = "Direkt im Norden von Astranaar sind die Distelfellfurbolgs. Meine Späher berichten, dass ihre Anzahl in den letzten Monaten stark zugenommen hat. Wenn sie zu schnell anwächst, fassen sie vielleicht den Mut, Astranaar direkt anzugreifen!\n\nBegebt Euch ins Lager der Distelfelle und tötet so viele von ihnen, wie Ihr könnt.\n\nIch werde hier in Astranaar bleiben und Euren Bericht erwarten. Elune sei mit Euch, {class}.", sourceObjective = "Tötet 15 Furbolgs im Lager der Distelfelle im Eschental.", completion = "Gute Arbeit, {name}.\n\nWir stehen unter der ständigen Bedrohung durch die Furbolgs. Hoffentlich wird sie das etwas länger von uns fernhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13868] = { id = 13868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlechter Einfluss?", description = "Als Ihr die Habseligkeiten der toten Furbolgs durchsucht, die vor Euch liegen, fällt ein kleiner, offensichtlich von Trollen erschaffener Glücksbringer auf den Boden.\n\nAls Ihr den Glücksbringer berührt, bekommt Ihr umgehend das Gefühl, dass es im Wald nicht mit rechten Dingen zugeht. Ein Gefühl der Unruhe und Verderbtheit durchdringt das Objekt.\n\nIhr hüllt es in ein Tuch, verstaut es in Eurem Gepäck und beschließt, es Raene Wolfsläufer zu zeigen, wenn Ihr das nächste Mal in Astranaar seid.", sourceObjective = "Überbringt den TrollglücksbringerRaene Wolfsläufer in Astranaar im Eschental.", progress = "Was beunruhigt Euch, {class}?", completion = "Ein Trollglücksbringer? Was fangen die Furbolgs mit so einem Ding an?\n\nIhr habt recht. Ein Gefühl von Verderbtheit umgibt dieses Artefakt... Sogar ich kann das spüren.\n\nEs gibt hier jemanden, der in der Lage sein müsste, zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13869] = { id = 13869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bergt die Überreste", description = "Die Satyrn haben den Bäumen fürchterlichen Schaden zugefügt, aber das ist nichts im Vergleich zu dem Gemetzel, das die Orcs veranstaltet haben!\n\n<Das Urtum zittert sichtbar vor Wut. Seine Blätter fallen rings um Euch zu Boden.>\n\n{race}, begebt Euch die Straße entlang zum Holzfällerlager und holt die Überreste dieser Bäume, Treants und Urtume, welche die Horde in ihren besten Jahren gefällt hat.", sourceObjective = "Sammelt 10 Stück Holz des Kriegshymnenklans.", progress = "Habt Ihr die Überreste, {race}?", completion = "Ich lebe schon lange friedlich in diesem Wald, aber wenn ich sehe, was diese Orcs hier veranstalten, dann würde ich sie am liebsten in Grund und Boden stampfen!\n\nIch werde diesem Holz jetzt seine letzte Ruhe geben. Habt Dank für Eure Hilfe, {name}. Ich werde es Euch nie vergessen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13870] = { id = 13870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besser geht's nicht", description = "Nun gut, {class}, besser geht es nicht.\n\nDie Elfen sind dabei, sich von Euren letzten Taten zu erholen. Das ist der günstigste Augenblick, um in das Holzfällerlager vorzustoßen!\n\nBegebt Euch dorthin und sprecht mit Vorarbeiter Gorthak. Er wird Euch erklären, wie Ihr die Diplomatin am sichersten begleitet.\n\nViel Glück!", sourceObjective = "Krokk will, dass Ihr das Holzfällerlager des Kriegshymnenklans betretet und mit Vorarbeiter Gorthak sprecht.", completion = "<Gorthak seufzt enttäuscht.>\n\nWenn Ihr doch nur vor einer Stunde eingetroffen wäret...\n\nDie Diplomatin wurde von einem Auftragsmörder der Elfen tödlich verwundet.\n\nWie der Feind in der Lage war, das Lager unentdeckt zu infiltrieren bleibt uns ein Rätsel.", sourceObjectiveStatus = "unverified-source-field" }
quests[13871] = { id = 13871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wachen!", description = "Es ist nicht so, als ob ich nicht schon genug um die Ohren hätte!\n\nDiesen Ort am Laufen zu halten ist schon schwer genug, ohne dass die Elfen und Draenei uns ständig belästigen.\n\nJetzt schleicht obendrein noch ein Auftragsmörder im Lager umher, der eine wichtige Diplomatin getötet hat... Während meiner Wache!\n\nWer auch immer es war, er kann noch nicht weit sein, {class}. Durchsucht das Lager, bis Ihr ihn findet und dann rächt die Diplomatin!\n\nZumindest kann ich dann den Kopf des Mörders in Händen halten, wenn ich mich vor Höllschrei rechtfertigen muss.", sourceObjective = "Vorarbeiter Gorthak will, dass Ihr ihm den Kopf eines Assassinen der Kaldorei bringt.", progress = "Mich interessiert nur eins, {race}.\n\nIst der Auftragsmörder tot?", completion = "Gute Arbeit, {class}.\n\nEine letzte Bitte – Es ist vermutlich das Beste, wenn keiner meiner Arbeiter erfährt, dass dieser Mörder jemals existiert hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13872] = { id = 13872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Weisheit der Worgen", description = "Der Mann, der mir direkt gegenübersteht, ist als Hephaestus Pilger bekannt. Er ist einer der Worgen.\n\nEr und seine Schwester kamen vor nicht allzu langer Zeit nach Astranaar, als sie einen neuen Ort zum Leben suchten. Soweit ich das sagen kann, ist er daran interessiert, dem Irdenen Ring bei der Katastrophe zu helfen. Seine Schwester ist sogar noch mächtiger. Sie ist nach Osten gereist, um dem Schamanen zu helfen, sich um den Vulkan zu kümmern.\n\nVielleicht kann er helfen. Bringt den Glücksbringer zu ihm und hört, was er darüber denkt.", sourceObjective = "Bringt den Trollglücksbringer zu Hephaestus Pilger in Astranaar im Eschental.", progress = "<Der Worgen sieht Euch ausdruckslos an, als Ihr Euch nähert.>", completion = "<Er sieht auf die Holzschnitzerei in Eurer ausgestreckten Hand. Der Worgen greift danach und nimmt sie an sich.>", sourceObjectiveStatus = "unverified-source-field" }
quests[13873] = { id = 13873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sheelahs Vermächtnis", description = "Ich... Ich kann nicht glauben, dass sie von uns gegangen ist. Es ist alles so schnell gegangen...\n\nIch muss Euch wohl danken, dass Ihr meine Herrin gerächt habt. Dafür habt meinen Dank und den von Silbermond.\n\nIn Ihrer Weisheit hat meine Lady Ihr Ende vorausgesehen. Sie hat ein Sendschreiben vorbereitet für den Fall, dass ihr irgendetwas zustoßen würde.\n\nWir sollten uns einem Gefolge aus Orgrimmar anschließen, am Wegekreuz nördlich von hier. Bitte, {race}, trefft sie an unserer statt und sorgt dafür, dass die Nachricht übergeben wird.", sourceObjective = "Wächter Menerin will, dass Ihr Sheelahs versiegelten Brief an Wächter Gurtar übergebt.\n\nBereitgestellter Gegenstand:", completion = "<Gurtar hört Euch zu, als Ihr ihn über Sheelahs Tod unterrichtet.>\n\nIch werde dies Höllschrei persönlich übergeben, {race}.\n\nIn der Zwischenzeit könntet Ihr etwas für mich tun...", sourceObjectiveStatus = "unverified-source-field" }
quests[13874] = { id = 13874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Bann der Glücksbringer", description = "Die Furbolgs begehren etwas, das ihnen nicht gehört.\n\n<Hephaestus dreht den Glücksbringer in seiner Hand und lässt ihn dann fallen.>\n\nDiese Schnitzerei besitzt die Eigenschaft, langsam jene zu verderben, die keine Trolle sind. Soweit ich sehen kann, haben die Furbolgs das schon einmal gemacht. Manche lernen's nie.\n\nZweifellos horten sie die meisten Glücksbringer in der Höhle der Distelfelle nördlich ihres Dorfes.", sourceObjective = "Sammelt 8 Trollglücksbringer.", progress = "Glaubt Ihr, dass Ihr schon alle Trollglücksbringer aus der Höhle der Distelfelle gesammelt habt?\n\nFalls auch nur einer verbleibt, wird der Stamm der Distelfelle weiterhin von ihm beeinflusst werden und schließlich diesen Ort angreifen.", completion = "<Hephaestus nickt langsam, während er Euch direkt in die Augen blickt.>\n\nIhr habt vermutlich die Distelfelle vor sich selbst beschützt, zumindest vorerst. Jedenfalls so lang sie nun davon absehen können, mächtige Objekte zu stehlen, die ihnen nicht gehören.\n\nSoweit ich das sehe, haben die Nachtelfen Probleme mit dem anderen Furbolgstamm im Süden. Darüber möchte Raene mit Euch sprechen.\n\nWie dem auch sei, es gibt dringlichere Angelegenheiten, bei denen ich Euch um Eure Unterstützung bitten möchte.", sourceObjectiveStatus = "unverified-source-field" }
quests[13875] = { id = 13875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gurtars Bitte", description = "Ich hätte noch eine persönliche Bitte an Euch, {class}.\n\nEs ist viele Monde her, seitdem ich meine Liebste gesehen habe, Draaka. Es werden noch viele weitere verstreichen, bis wir uns wiedersehen können. Ich fürchte, dass nach so langer Zeit ihre Liebe für mich schwinden wird.\n\nDieser Zopf hat für uns beide eine besondere Bedeutung, und auch der dornige Blutkelch, die Blume, die in dieser Region wächst.\n\nIch bitte Euch, diese Blumen zu pflücken und sie mit dieser Schnur zu binden. Dann übergebt Draaka das Geschenk in meinem Namen.", sourceObjective = "Wächter Gurtar will, dass Ihr den Blutkelchzopf an Draaka im Splitterholzposten übergebt.", progress = "Hallo, {name}.", completion = "<Draaka erfasst sofort die Bedeutung dieses Geschenks und beginnt zu weinen.>\n\nOh, {name}. Habt Dank für dieses Geschenk! Es bedeutet mir mehr, als Ihr ahnen könnt.\n\nEr hat nicht vergessen...", sourceObjectiveStatus = "unverified-source-field" }
quests[13876] = { id = 13876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu weit entfernt", description = "Ja, ich spreche Eure Sprache, {race}.\n\nWir Furbolgs waren schon einmal Opfer dieser Form von Verderbnis. Vor nicht allzu langer Zeit stahl unser Anführer den Götzen von Remulos. Das von Dämonen verderbte Ding verhexte den gesamten Stamm und unsere Erlösung wurde nur notdürftig durch einen Druiden herbeigeführt, der Broll Bärenfell heißt.\n\nAber dieses Mal haben wir nicht gestohlen. Die Trolle von Zoram'gar gaben uns die Glücksbringer als ein Zeichen der Freundschaft. Eine tödliche Freundschaft, wie es scheint.\n\nUnser Häuptling Dal Blutklaue ist nicht mehr zurechnungsfähig. Betretet die Höhle und kehrt mit seinen Glücksbringern zurück.", sourceObjective = "Gelangt in den Besitz von Blutklaues Sammlung.", progress = "Nun? Die Zukunft der Distelfelle lastet auf Euren Schultern, {race}.", completion = "Es wurde getan, was getan werden musste. Da Dal unser Anführer ist, hat seine Erkrankung durch die Trollglücksbringer uns zerstört.\n\nFür die Gesundheit und die Würde unseres Stammes war es gut, dass Ihr es wart, Fremdling. Auf diese Weise wird es keinen Bürgerkrieg unter uns geben und wir finden leicht einen neuen Anführer... hoffentlich jemanden, der nicht so schnell Fremden vertraut. Vielleicht habe auch ich mich dessen schuldig gemacht?\n\nHier, erlaubt mir unsere Schuld zu begleichen, bevor sich unsere Wege für immer trennen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13877] = { id = 13877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tanz auf dem Vulkan", description = "<Der Worgen starrt Euch durchdringend an, bevor er seine Bitte vorträgt.>\n\nDer Vulkan droht, das gesamte Eschental zu verschlingen, wenn wir nicht rasch handeln. Lasst Euch gesagt sein, dass dies kein natürlicher Ausbruch war.\n\nMeine Schwester Sabina ist mächtig. Sie ist nach Osten zur Grenze des Lavastroms am Donnergipfel direkt nördlich der Straße gegangen. Dort erbittet sie die Hilfe anderer Elemente gegen den Feuerlord, der diese Zerstörung verursacht hat.\n\n{name}, begebt Euch zu ihr und helft ihr, so gut Ihr könnt.", sourceObjective = "Sprecht mit Sabina Pilger am südlichen Rand des Lavastroms am Donnergipfel im Eschental.", completion = "Mein Bruder muss Euch gesandt haben. Er hätte das nicht getan, wenn Ihr nicht in der Lage wäret, etwas zu tun, was getan werden muss.\n\nIch hoffe um unser aller Willen, dass er recht hat.\n\nDie Elementare hier sind nun meine Verbündeten. Ihr müsst tun, was sie Euch sagen, wenn wir die Zerstörung vom Rest des Eschentals verhindern wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13878] = { id = 13878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch Feuer und Flamme", description = "Helft mir, {class}! Schweinemenschen kommen und zünden Ställe an – Feuer! Feuer!\n\n<Dorak jammert etwas Unverständliches, bevor es Euch gelingt, ihn zu beruhigen.>\n\nWölfe drinnen noch angekettet. Jemand muss die kleinen Wölfe retten!", sourceObjective = "Brecht die Ketten auf und befreit die Wölfe aus den brennenden Ställen.", progress = "Heiß!", completion = "Ihr habt die Wölfe gerettet! So mutig! Eines Tages bekommt Ihr vielleicht einen Wolf wie diesen als Reittier.\n\n<Dorak sieht auf die brennenden Ställe, dann zum nahegelegenen Fluss.>\n\nWas soll ich nun tun?", sourceObjectiveStatus = "unverified-source-field" }
quests[13879] = { id = 13879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnergipfel", description = "Seid gegrüßt, {class}!\n\nIch gratuliere zu Eurem siegreichen Angriff auf Astranaar. Die Elfen werden diese Schmach nicht so schnell vergessen, die sie durch Eure Hand erlitten haben.\n\nAber Ihr müsst wissen, dass die Elfen nicht das einzige Hindernis sind, dass der Eroberung des Eschentals durch die Horde im Wege steht...\n\nIm Osten benötigt ein Schamane des Irdenen Rings Hilfe bei einer anderen Krise. Ihr findet ihn in der Nähe des Fußes des Vulkans Donnergipfel.", sourceObjective = "Broyk will, dass Ihr Stikwad am Donnergipfel findet.", completion = "<Der Goblin starrt Euch an und blinzelt einige Male bevor er spricht.>\n\nDie Geister haben mir geflüstert, dass diese Hilfe bald eintrifft.\n\nVerzeiht meine Überraschung, aber ich hatte darauf gehofft, dass die Geister jemanden schicken der etwas... heldenhafter ist.\n\nDie Elementare sind meine Vertrauten. Hört sie an und leistet ihren Anordnungen Folge. Falls wir scheitern, wird vom Eschental nichts mehr übrigbleiben, für das es sich zu kämpfen lohnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13880] = { id = 13880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heiße Lava", description = "<Der riesenhafte Erdelementar starrt auf Euch herab.>\n\nDer Lavastrom muss aufgehalten werden, wenn wir überleben wollen. Ich werde Euch einen Teil meiner Kraft übertragen. Verwendet sie, um die Lavafelsspalten zu füllen!", sourceObjective = "Verwendet das Geschenk der Erde, um 8 Lavafelsspalten zu füllen.", progress = "Fertig?", completion = "Gut gemacht, {race}. Lord Magmathars Feuer ist nun gefangen und wieder fest in der Erde verschlossen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13881] = { id = 13881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufgezehrt", description = "Meine größte Sorge gilt den Distelbärfamilien, die diese Wälder behausen. Südlich von hier, hinter dem Bärenschrein, ist eine gesamte Generation der Bären erkrankt. Schrecklich erkrankt.\n\n{name}, ich weiß nicht, woran sie leiden, aber es scheint sie von innen aufzuzehren. Der Gedanke, dass eine gesamte Generation nicht mehr zu retten ist, ist entsetzlich, aber wir müssen sie töten, damit ihre Körper der Erde zurückgegeben werden.\n\nUnd was noch wichtiger ist, wir müssen den Ursprung der Krankheit finden. Untersucht den See, aus dem die Bären trinken.", sourceObjective = "Tötet 6 aufgezehrte Distelbären und untersucht den See, von dem die Distelbären trinken.", completion = "<Kathrena schaudert bei der Beschreibung der in Mitleidenschaft gezogenen Tiere und dem furchtbaren Gerät auf dem Boden des Sees.>\n\n{name}, das ist grauenvoll. Was ist das für ein Ding und wo kommt es her? Etwas zehrt diese Tiere auf, sowohl körperlich als auch spirituell. Ich hatte damit gerechnet, dass die Satyrn oder eine Krankheit die Schuld trügen, aber es scheint einen doch eher... unnatürlichen Grund dafür zu geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13882] = { id = 13882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Samenkörner des Lebens", description = "Etwas versucht, das Leben an der Dunkelküste aufzuzehren! Ich werde mich umhören, ob jemand etwas über - das Ding - weiß, das Ihr gefunden habt. In der Zwischenzeit müssen wir uns aber auch um die Wildtiere kümmern, damit ihnen nicht noch weiteres Leid geschieht.\n\nKönnt Ihr ein paar Materialien für mich besorgen? Ich brauche Leben in allen möglichen Formen. Sprecht mit Onu hier am Hain, um die Saat der Erde zu erhalten. Fangt einen Dunkelküstenirrwisch, um die Saat des Himmels zu erhalten, und besorgt die Saat des Meeres von den Muscheln an der Küste westlich von hier.", sourceObjective = "Sammelt die Saat der Erde, die Saat des Meeres und die Saat des Himmels.", progress = "Leben ist mächtig, {name}. Konzentriert in seiner reinsten Form kann es alles überstehen. Eines Tages wird auch die Dunkelküste von den Wunden genesen. Habt Ihr alles gefunden, was ich brauche?", completion = "Perfekt - das ist alles, was ich brauche. Hattet Ihr Spaß beim Irrwischfangen? Als kleines Mädchen habe ich immer Irrwische im Eschental herumgejagt.\n\n<Kathrena schwelgt in Erinnerungen. Plötzlich verdunkelt sich ihr Blick.>\n\nIch befürchte, ich weiß, womit wir es hier zu tun haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13883] = { id = 13883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Wrack neben dem anderen", description = "Stümperhaftes Handwerk! Es gibt keine andere Erklärung...\n\nDiese Schiffe müssen in großer Eile zusammengeflickt worden sein. Ganze Panzerungsplatten fallen ab, ohne jemals einen Treffer abgefangen zu haben!\n\nIch zeige ihnen, wie man es richtig macht. Aber zuerst müsst Ihr für mich die Teile vom Meeresboden bergen.\n\nKehrt mit den Teilen zu mir zurück und ich erledige den Rest.", sourceObjective = "Bergt 10 Teile versunkenes Altmetall.", progress = "Habt Ihr die Panzerungsplatten geborgen, {race}?", completion = "Gute Arbeit, {race}.\n\nIch werde ihnen zeigen, wie ein gepanzertes Schiff gebaut werden sollte!", sourceObjectiveStatus = "unverified-source-field" }
quests[13884] = { id = 13884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerlöscher", description = "Wir müssen uns zunächst um Lord Magmathars Lakaien kümmern, wenn wir dieses Gebiet zurückerobern wollen und der hitzigen Zerstörung des Waldes Einhalt gebieten wollen.\n\nDie Lavawüter auf dem Strom im Norden werden durch ihr Element gestärkt. Ich fürchte, wenn Ihr auf Euch gestellt seid, habt Ihr keine Chance gegen sie.\n\nWenn Ihr bereit seid, sprecht mich wieder an und ich werde einen meiner Helfer für Euch beschwören.", sourceObjective = "Tötet 10 Lavawüter. Falls Ihr einen weiteren gefrierenden Woger benötigt, sprecht mit Arctanus.", completion = "Ihr habt Euch auf dem Schlachtfeld wacker geschlagen. Dennoch hat Lord Magmathar Euch leider bemerkt und die Zerstörung, die Ihr über seine Lakaien gebracht habt.\n\nIhr werdet Euch um ihn kümmern müssen, oder er verbrennt Euch bei lebendigem Leibe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13885] = { id = 13885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung der Dunkelküste", description = "Nun da wir wissen, dass unsere Vorsorgemaßnahmen funktionieren, sollten wir so viel Land abdecken wie möglich.\n\nWir können einen der Hippogryphen benutzen, aber alleine kann ich nichts ausrichten. Sprecht mit meinem Freund Orseus beim Flugmeister vor dem Hain. Sagt ihm Bescheid, wenn Ihr so weit seid. Ich werde Euch dort treffen. Wir werden die Dunkelküste von der Luft aus abdecken und so viele Tiere wie möglich schützen!", sourceObjective = "Sprecht mit Orseus vor dem Hain der Uralten und besteigt einen Hippogryphen. Beschützt aus der Luft 8 Weißschwanzhirsche und -rehe, 8 ergraute Distelbären und 8 Mondpirschermatriarchinnen oder Mondpirscherpatriarchen vor der Verzehrung.", completion = "Die Tiere sind also in Sicherheit. Ich danke Euch, vielen Dank!\n\nJetzt müssen wir unsere Aufmerksamkeit dem Ursprung der Verzehrung widmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13886] = { id = 13886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vortex", description = "Es ist an der Zeit, {name}. Wenn Ihr Euch gewappnet habt, sprechen wir wieder miteinander und ich werde einen Wirbelnden Vortex beschwören, der Eure Schritte zu den Himmeln über dem Donnergipfel beschleunigt.\n\nLeitet die Kraft des Irdenen Rings durch den Elementar, um Lord Magmathar zu vernichten, sodass wir ihn wieder ins Gleichgewicht bringen.", sourceObjective = "Verwendet die Kräfte des Wirbelnden Vortexes, um Lord Magmathar zu vernichten.", completion = "Es ist vollbracht. Die Kräfte des Feuers sind beruhigt und die vier Elemente befinden sich wieder in Harmonie.\n\nIhr habt den Rest des Eschentals mit Eurem Mut und Euren heldenhaften Taten gerettet, {name}. Wir schulden Euch unseren ewigen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[13887] = { id = 13887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gifthauteier", description = "Jetzt, da Ihr gegen das Sauriergift immun geworden seid, könnt Ihr mit den Tieren und ihren Eiern sicher umgehen. Gifthäute sind ziemlich bösartig und müssen vom Moment des Schlüpfens an trainiert werden.\n\nWenn Ihr einen reiten wollt, dann werdet Ihr ein ungeschlüpftes Ei benötigen. In den gesamten Marschen verteilt gibt es einige Ravasauriernester. Sucht nach Eiern mit helleren Schalen - das sind diejenigen, aus denen später Gifthäute schlüpfen werden.\n\nWenn Ihr mir einige Eier bringt, werde ich Euch gestatten, eins zu behalten und unter meiner Aufsicht aufzuziehen.", sourceObjective = "Bringt Mor'vek im südöstlichen Teil der Marschen 4 Eier von Gifthautravasauriern.", progress = "Habt Ihr die Eier gefunden?", completion = "Gute Arbeit. Wirklich, ich bin erstaunt, dass Ihr so viele gefunden habt. Ihre Zahl scheint in jedem Gelege zurückgegangen zu sein.\n\nIch werde Euch einen der frisch geschlüpften Gifthäute aufziehen lassen. Er wird sich vermutlich nicht zieren, Euch wissen zu lassen, was er braucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[13888] = { id = 13888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vortex", description = "Es ist an der Zeit, {name}. Wenn Ihr Euch gewappnet habt, sprechen wir wieder miteinander und ich werde einen Wirbelnden Vortex beschwören, der Eure Schritte zu den Himmeln über dem Donnergipfel beschleunigt.\n\nLeitet die Kraft des Irdenen Rings durch den Elementar, um Lord Magmathar zu vernichten, sodass wir ihn wieder ins Gleichgewicht bringen.", sourceObjective = "Verwendet die Kräfte des Wirbelnden Vortexes, um Lord Magmathar zu vernichten.", completion = "Ihr habt es geschafft! Die Geister haben sich doch nicht getäuscht!\n\nDie Kräfte des Feuers sind beruhigt und die vier Elemente befinden sich wieder in Harmonie.\n\nDem Rest des Eschentals bleibt ein Schicksal in Flammen erspart. Der Irdene Ring ist Euch zu ewigem Dank verpflichtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[13889] = { id = 13889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sooooo hungrig", description = "Das Gifthautjunge sieht Euch erwartungsvoll an und beginnt dann, ein Piktogramm in den Boden zu kratzen.\n\nDie Zeichnungen sind grob, aber Ihr könnt die Umrisse von Dimetrodonten, Stegodonten und Pterrordaktylen ausmachen. Als der Raptor die Zeichnung vervollständigt hat, sieht er wieder zu Euch auf, fletscht seine Zähne und schnappt ein paar Mal mit dem Maul.\n\nAnscheinend hat Euer Gifthautjunges Hunger auf frisches Fleisch von diesen Tieren. Findet und tötet Dimetrodonten, Stegodonten oder Pterrordaktylen im Krater von Un'Goro und füttert Euer hungriges Junges mit ihrem Fleisch.", sourceObjective = "Euer Gifthautjunges möchte, das Ihr 15 frische Dinosaurierfleischstücke an ihn verfüttert.", completion = "Das Gifthautjunge scheint mit der gewaltigen Mahlzeit, die Ihr ihm serviert habt, durchaus zufrieden. Es lässt sich allerdings schwer sagen, wann es wieder hungrig sein wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[13890] = { id = 13890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schürt das Feuer", description = "Dies ist keine leichte Aufgabe, {race}!\n\nEs treffen weitere Schiffe ein und ohne den Leuchtturm werden sie sich verirren – oder noch Schlimmeres! Hiermit wird Euch die Aufgabe übertragen, sein Feuer am Brennen zu erhalten.\n\nSammelt den Tran der Hydras in diesen Gewässern und bringt ihn dann zu dieser Schmiede hier, damit daraus Öl hergestellt wird.\n\nWerft Ihr dieses Öl in das Feuer des Leuchtturms, wird uns das die Zeit verschaffen, die wir benötigen.", sourceObjective = "Kommandant Grimmfang in Zoram'gar will, dass Ihr das Öl einer Nebelpeitscherhydra ins Feuer des Leuchtturms gießt.", completion = "Gute Arbeit, {race}!\n\nKeine Schiffe werden mehr auf Grund laufen - dank Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[13891] = { id = 13891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Verschlinger der Dunkelküste", description = "Jetzt, da die Kreaturen der Dunkelküste in Sicherheit sind, sollten wir unsere Aufmerksamkeit dem Artefakt widmen, das Ihr im See gefunden habt. Ich glaube, es handelt sich dabei um die Arbeit der Diener der Alten Götter. Wir werden diese Feinde mit den lebensspendenden Energien zerstören, die die Dunkelküste besitzt! Bringt den Lebensbringerschössling zum Ufer des Sees südlich von hier. Bewegt ihn über die Wasser des Sees; das sollte das alte Artefakt ausschalten.\n\nSeid vorsichtig, {name}. Das Artefakt wird sicherlich von irgendetwas bewacht.", sourceObjective = "Verwendet den Lebensbringerschössling am Ufer des flachen Sees südlich des Hain der Uralten und zerstört das verschlingende Artefakt und seinen Bewacher.", progress = "Ich wage es gar nicht, zu fragen, {name}, konntet Ihr das Artefakt zerstören? Was ist mit dem Bewacher?", completion = "Bei Elune, wie seht Ihr denn aus? Das muss ein heftiger Kampf gewesen sein! Ihr seid voller... nun, es sieht ein wenig wie Fischsuppe aus...\n\nWenn ein einfacher Diener solch Leid hier an der Dunkelküste auslösen kann, möchte ich mir gar nicht erst überlegen, welche Katastrophen einer der Alten anrichten könnte.\n\nWenigstens sind die Tiere vorerst in Sicherheit. Ich werde den von Euch geschaffenen Schössling pflanzen, um dem zerstörten Land bei der Regeneration zu helfen. Ich danke Euch, {name}! Ich würde Euch ja umarmen, aber, Ihr wisst ja... Fischsuppe.", sourceObjectiveStatus = "unverified-source-field" }
quests[13892] = { id = 13892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Spuren hinterlassen", description = "Südwestlich von hier liegt der Leichnam eines Wesens, das in irgendeiner Verbindung zu den Alten Göttern steht, die die Schattenhammerkultisten verehren.\n\nEs wurde vor unserer Zeit besiegt - wenn nicht von den Titanen selbst, so sicherlich von einer ihrer Schöpfungen.\n\nIn der letzten Zeit haben wir zunehmend Aktivitäten der Kultisten beobachtet und das kann nur bedeuten, dass uns etwas Schreckliches bevorsteht.\n\nWir müssen herausfinden, was sie dort vorhaben, und warum. Nehmt diese Figur. Sie wird Euch dabei helfen, bei Euren Untersuchungen unbemerkt zu bleiben.", sourceObjective = "Schleicht in die Meistergleve und beobachtet mit Hilfe der Pantherfigur die Schattenhammerkultisten.", completion = "Das sind schreckliche Neuigkeiten, {name}. Wenn Ihr recht habt, so müssen wir schnell und entschieden handeln.\n\nWir können nicht zulassen, dass \"Soggoth\" wieder zum Leben erweckt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[13893] = { id = 13893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soggoth und Kronn", description = "Die Meistergleve ist der Ort einer uralten Schlacht, {name}. Die Titanen haben zwanzig ihrer Steinriesen gegen Soggoth ausgesandt.\n\nVon diesen zwanzig Riesen hat nur einer überlebt.\n\nAuf den Tafeln steht geschrieben, dass Kronn, der größte aller Steinriesen, sich von Soggoths Ranken hat einfangen lassen - nur lange genug, um dem Schädel der Kreatur näher zu kommen - nahe genug für sein mächtiges Schwert.\n\nEs ist gut, dass er tot ist... wir haben nicht wirklich zwanzig weitere Steinriesen zur Verfügung, um ihn erneut aufzuhalten.", sourceObjective = "Kehrt mit den neuen Informationen zu Larien beim Hain der Uralten zurück.", completion = "Die Geschichte des Zwerges ist besorgniserregend... doch sehr aufschlussreich. Es scheint, als hätten wir mehr als eine Möglichkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[13895] = { id = 13895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die schlummernden Uralten", description = "Wir haben keine zwanzig Steinriesen, um uns des Feindes anzunehmen, aber wir Riesen aus uraltem Holz sind so stark wie jeder Fels.\n\nSeht Euch um, {race}. Mein Volk schläft... und doch werden sie in Zeiten der Not dem Horn des Hüters folgen.\n\nIhr könnt Aros, den Hüter des Hains, jenseits der Brücke nordöstlich von hier finden.\n\nBerichtet ihm vom Ernst der Lage.", sourceObjective = "Findet Aros nordöstlich vom Hain der Uralten an der Dunkelküste.", completion = "Aros Körper ist leblos, doch er ist noch warm. Vielleicht sind seine Mörder in der Nähe.", sourceObjectiveStatus = "unverified-source-field" }
quests[13896] = { id = 13896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgegrabenes Wissen", description = "Hört gut zu, {name}. Wir müssen mehr über unseren Feind in Erfahrung bringen.\n\nSüdwestlich von hier, hinter der Meistergleve, sind ein paar Ausgrabungsleiter der Zwerge, die die Ruinen in der Nähe untersuchen.\n\nVielleicht haben sie Wissen zu Tage gebracht, das uns nützlich sein könnte.", sourceObjective = "Sprecht mit Archäologe Groff bei Wirrbarts Ausgrabung.", completion = "Ja, wir wissen das eine oder andere über Soggoth. Die Frage ist, ob Ihr wirklich mehr erfahren möchtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[13897] = { id = 13897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um die Dunkelküste", description = "Die Urtume des Hains sind uns zu Hilfe gekommen, {name}. Ich sehe selbst in diesem Augenblick durch ihre Augen.\n\nDer Schattenhammer muss sein Ritual schneller durchführen als ursprünglich geplant und bisher haben sie nur einen Teil des gefürchteten Soggoth wieder zum Leben erwecken können.\n\nZerstört diesen Teil, bevor es zu spät ist, {name}. Ich werde andernorts gebraucht.\n\nKehrt zu den Druiden am Hain der Uralten zurück, wenn Ihr fertig seid. Sie werden Euch weitere Anweisungen erteilen.", sourceObjective = "Tötet den Avatar von Soggoth in der Meistergleve.", completion = "Nun können wir in Frieden ruhen, {name}. Es scheint, als wurde die Dunkelküste gerettet. Und Ihr verdient den Dank dafür.", sourceObjectiveStatus = "unverified-source-field" }
quests[13898] = { id = 13898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Blatt wendet sich gegen uns", description = "Wir können die Naga nicht ungestraft davonkommen lassen, {name}. Der Mord an dem Hüter des Hains ist eine Kriegserklärung.\n\nIhr könnt ihre Höhle auf der Insel Nazj'vel weit im Südwesten finden.\n\nÜberbringt ihnen eine deutliche Nachricht.", sourceObjective = "Tötet 8 Myrmidonen der Dunkelschuppen.", completion = "Gut gemacht, {name}. Die Naga wünschen die Zerstörung und Unterwerfung aller Oberflächenbewohner. Zögert nicht, sie aus unseren Landen zu vertreiben und sie zurück in die schattigen Tiefen des Ozeans zu drängen, dort, wo sie hin gehören.", sourceObjectiveStatus = "unverified-source-field" }
quests[13899] = { id = 13899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kriegsfürst der Dunkelschuppen", description = "Wenn die Naga sich mit dem Schattenhammer verbünden wollen, so gnade ihnen Elune.\n\nBegebt Euch zu ihrer Höhle auf der Insel Nazj'vel und findet den Anführer der Naga, den Kriegsfürst Zornrücken.\n\nVielleicht kann das Horn der Urtume noch gerettet werden.", sourceObjective = "Tötet Kriegsfürst Zornrücken in Nazj'vel.", completion = "Der Kriegsfürst scheint das Horn nicht bei sich zu haben. Möglicherweise sprach er die Wahrheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[13900] = { id = 13900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Opfer für Azshara", description = "Der Kriegsfürst sagte, dass das Horn der Urtume als Opfergabe an Azshara oben in Nazj'vel gegeben wurde.\n\nVielleicht ist es noch nicht zu spät, das alte Relikt vor der Zerstörung zu retten.", sourceObjective = "Haltet die Priesterinnen der Dunkelschuppen davon ab, das Horn der Urtume oben in Nazj'vel Azshara zu opfern.", completion = "Ihr habt gute Arbeit geleistet, {name}. Leider ist die Schlacht noch nicht gewonnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13901] = { id = 13901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefe Verzweiflung", description = "Dieses Nagaproblem erweist sich als größer, als es auf den ersten Blick ersichtlich war, {class}. Es scheint, als ob sich die Situation nicht einfach dadurch klärt, dass wir ihre Anzahl verringern. Um sie in ihre Schranken zu weisen, müssen wir einen nachhaltigeren Eindruck auf sie machen.\n\nReist zum nördlichen Ende des Zoramstrands und betretet die Tiefschwarze Grotte. Sobald Ihr dort seid, zeigt den Naga, dass ihre Anwesenheit in diesem Gebiet nicht länger toleriert werden wird!", sourceObjective = "Tötet 6 Gezeitenpriesterinnen der Tiefschwarzen Grotte.", completion = "Ausgezeichnet!\n\nDie Naga sollen zurück ins Meer, wo sie hergekommen sind!", sourceObjectiveStatus = "unverified-source-field" }
quests[13902] = { id = 13902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Offensive festigen", description = "Unsere Arbeit an der Dunkelküste ist längst nicht vorbei. Wir haben die Landmassen vor dem Zerbersten bewahrt, aber unsere Feinde sind noch immer stark hier vertreten.\n\nIch möchte, dass Ihr südlich von hier ein paar Druiden am Hain der Uralten aufsucht. Sie werden von einem alten Freund von mir angeführt, von Balren von der Klaue.\n\nSagt ihnen, die Zeit ist reif, um die Schlacht zu unseren Feinden zu bringen. Ich werde nachkommen und sie unterstützen, sobald wir diese Gegend stabilisiert haben.", sourceObjective = "Sprecht mit Balren von der Klaue am Hain der Uralten an der Dunkelküste.", completion = "Wenn Malfurion Euch vertraut, so werde ich es ihm gleichtun. Ihr werdet sehen, dass unsere Feinde im Süden weitaus zahlreicher sind als wir.\n\nWo rohe Gewalt und Übermacht gegen uns sind, werden Strategie und Täuschung unsere größten Vorteile sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13903] = { id = 13903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorishigelee", description = "Das Gifthautjunge sieht Euch erwartungsvoll an und beginnt dann, ein Piktogramm in den Boden zu kratzen.\n\nDie Zeichnungen des Jungen scheinen verschiedene Arten großer Insekten darzustellen, vielleicht die Gorishisilithiden. Das Junge beendet seine Zeichnung, zeigt mit einem kurzen Arm darauf, schnappt mit dem Kiefer und leckt sich das Mäulchen.\n\nEs möchte wohl, dass Ihr zur Wuchernden Narbe, im Zentrum des südlichen Kraters von Un'Goro geht und Silithidenfleisch sammelt. Wenn Ihr das Fleisch habt, gebt es Eurem hungrigen Jungen zu fressen.", sourceObjective = "Euer Gifthautjunges möchte, das Ihr 10 Stück Silithidenfleisch an ihn verfüttert.", progress = "Das Junge legt den Kopf schief und sieht Euch an.", completion = "Das Gifthautjunge grinst Euch mit spitzen Zähnen zufrieden an und rollt sich dann zum Schlafen zusammen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13904] = { id = 13904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pochiert, gerührt oder roh?", description = "Der Magen des Gifthautjungen knurrt, als es mit seinen Ärmchen wedelt, um Eure Aufmerksamkeit zu bekommen. Es beginnt, die Umrisse von Silithiden in die Erde zu kratzen, darunter einige Ovale. Es sieht Euch hoffnugsvoll an und deutet auf die Kreise.\n\nSie können nur Silithideneier darstellen. Der Giftige Unterschlupf im westlichen Tanaris, nahe der Grenze zum Krater von Un'Goro, wäre sicherlich ein guter Ort, um die Eier zu finden, die Euer kleines Junges haben möchte.", sourceObjective = "Euer Gifthautjunges möchte, das Ihr 12 Silithideneier an ihn verfüttert.", completion = "Euer Junges leckt sich das Mäulchen, nachdem es die Riesenportion Silithideneier verschlungen hat. Für einen Moment glaubt Ihr, es sieht ein wenig enttäuscht aus, dass die Fütterungszeit schon vorbei ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[13905] = { id = 13905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sengende Rocfedern", description = "Das Junge sieht Euch für einen Moment an, ein wenig, als ob es sich fragt, ob Ihr verstehen werdet. Es kratzt ein Bild von einem Paar Federn in die Erde, bevor es mit einer Klaue auf die Lederbänder um seine Ellbogen und Knie zeigt.\n\nEs sieht nicht hungrig aus, aber wofür könnten die Federn gut sein?\n\nEs will sie wohl als Schmuck haben, wie Ihr ihn an den anderen Raptoren gesehen habt. Die größten Federn findet man bei den sengenden Rocs, welche die großen Tierknochen in der westlichen Tanariswüste umschwärmen, nordöstlich des Disteltals.", sourceObjective = "Euer Gifthautjunges möchte, das Ihr ihm 5 Federn von sengenden Rocs bringt.", progress = "Euer Gifthautjunges sieht Euch erwartungsvoll an.", completion = "Das Gifthautjunge nimmt die Federn an sich und begutachtet sie, während es einige an seine Armbänder hält.", sourceObjectiveStatus = "unverified-source-field" }
quests[13906] = { id = 13906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie werden so schnell erwachsen", description = "Durch Eure fachmännische Fütterung und Pflege wird Euer Gifthautjunges schnell heranwachsen. Im Laufe seines Wachstums werden seine ersten Zähne durch bleibende ersetzt. Solltet Ihr die Milchzähne aufbewahren, werdet Ihr mit Leichtigkeit sagen können, wann es ausgewachsen genug sein wird, um zugeritten zu werden.\n\nEuer Junges wird Euch wissen lassen, was es braucht - gebt also genau Acht. Bringt mir Euren kleinen Ravasaurus und die Materialien für Euren Sattel, wenn er all seine Zähnchen verloren hat, und ich werde mich um den Rest kümmern.", sourceObjective = "Bringt 20 Gifthautzähnchen, das Gifthautjunge, 20 Stück Runenstoff, 20 unverwüstliches Leder und 80 Gold zu Mor'vek im südöstlichen Teil des Marschlands im Krater von Un'Goro.", progress = "Habt Ihr gut auf den Raptor achtgegeben?", completion = "Sieht aus, als hättet Ihr die Aufzucht überstanden, ohne einander umzubringen.\n\nDa, alles ist fertig. Ich habe Euren Gifthautravasaurus so abgerichtet, dass er Euch folgt, wenn Ihr in diese Pfeife blast.\n\nNur wenige besitzen die nötige Hingabe, um einen der kleinen Ravasaurier per Hand großzuziehen, aber sie sind die Mühe auf jeden Fall wert.", sourceObjectiveStatus = "unverified-source-field" }
quests[13907] = { id = 13907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ruinen säubern", description = "Die Großbärte aus Eisenschmiede haben mich geschickt, um nach Wirrbarts Ausgrabung zu sehen, als sie von dem Desaster erfuhren. Seht Euch nur um! Wertvolle Artefakte in das Meer geschwemmt und monatelange Ausgrabungen in wenigen Minuten zunichtegemacht.\n\nAls die Gezeitenwelle eintraf, vernichtete sie die Lager der Murlocs an der Küste. Gute Nachrichten? Nein, kein Glück für uns. Die Überlebenden suchen in den Ruinen Unterschlupf und fügen der Ausgrabung mehr Schaden zu, als es die Elemente je gekonnt hätten. Könntet Ihr Eure Watstiefel anziehen und Euch für mich um die Sache kümmern?", sourceObjective = "Tötet 10 Orakel der Grauflossen oder Flüchtlinge der Grauflossen, die in Wirrbarts Ausgrabung Unterschlupf suchen.", completion = "Bravo, {name}! Schauen wir die Lage doch jetzt noch einmal an.\n\nWie? MEHR Murlocs? Ich schwöre bei meinen Steinen, je mehr Murlocs man tötet, umso mehr scheinen aufzutauchen. Oder bilde ich mir das nur ein? Wir brauchen eine andere Vorgehensweise.", sourceObjectiveStatus = "unverified-source-field" }
quests[13908] = { id = 13908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufsatteln", description = "Euer Ravasaurus ist stark und gesund, und Ihr habt Euch wirklich gut aneinander gewöhnt. Ihr werdet ihn reiten können, sobald ich Euren Sattel und das Zaumzeug fertiggestellt habe. Genau wie Ihr müssen die Materialien speziell behandelt werden, um den Giften zu widerstehen, die der Raptor erzeugt.\n\nAlles, was Ihr tun müsst, ist mir etwas unverwüstliches Leder, Runenstoff und Geld für den Rest des Materials zu bringen. Dann werde ich den Sattel im Handumdrehen fertiggestellt haben.", sourceObjective = "Bringt Mor'vek im südöstlichen Teil der Marschen im Krater von Un'Goro 20 unverwüstliche Leder, 20 Runenstoff und 80 Gold.", sourceObjectiveStatus = "unverified-source-field" }
quests[13909] = { id = 13909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treibgut übrig?", description = "Wir werden eine Lösung finden, {name}. Wir brauchen nur ein bisschen zwergische Raffinesse. Denk nach, Groffy, denk schon!\n\nDie Murlocs wollen doch nur Unterschlupf, oder? Lasst uns konstruktiv sein. Das meine ich wortwörtlich.\n\nWährend der Katastrophe wurden alle möglichen Sachen an Land geschwemmt und ein paar der alten Hütten der Murlocs sind bestimmt noch benutzbar. Lauft an der Küste entlang und sucht für Murlocs geeignete Baumaterialien. Ihr werdet nicht lange suchen müssen.", sourceObjective = "Findet 5 Stück verwertbare Grauflossentrümmer an der Küste und am Wasser in der Nähe von Wirrbarts Ausgrabung.", progress = "Nass genug für Euch?", completion = "<Archäologe Groff schaut die Trümmer durch.>\n\nNaja, es findet sich kaum etwas, auf dem nicht herumgetrampelt wurde oder das nicht wie eine Toilette heruntergespült aussieht. Aber mit einem Dach drauf wird es schon ausreichen.\n\nSagt mir, {name}, habt Ihr Euch je als Architekten gesehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[13910] = { id = 13910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neues Zuhause", description = "Können wir es bauen? Natürlich! Westlich von der Ausgrabung habe ich ein Banner an der Küste aufgestellt. Der Sand ist stabil und eignet sich ebenso gut als Bauort wie jeder andere. Nehmt mein Werkzeug und die Trümmerstücke und baut diesen störrischen Plagegeistern ein neues Zuhause.", sourceObjective = "Baut eine Hütte für die Murlocs an der von Groff markierten Stelle an der Küste in der Nähe.", progress = "Und, was macht unser neues Heim mit Meerblick?", completion = "Haha, das klingt nach einem guten Haufen, den Ihr da gebaut habt. Sind sie darauf angesprungen? Gut, gut. Sehen wir mal, ob mein Plan erfolgreich ist.\n\n<Archäologe Groff beobachtet, wie aus allen Richtungen massenweise Murlocs zum Strand gelaufen kommen. Seine Augenbrauen ziehen sich enger und enger zusammen.>\n\nWas habe ich nur getan?", sourceObjectiveStatus = "unverified-source-field" }
quests[13911] = { id = 13911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der geistesabwesende Ausgrabungsleiter", description = "Und wer seid Ihr nochmal? {name}? Kenne ich Euch? Wenn die Liga Euch schickt, dann könnt Ihr ihnen gleich sagen, dass ich hierbleibe! Ich gehe nicht ohne meinen Fund. Ich hielt ihn bereits in den Händen! Und dann brach plötzlich Geschrei aus. Und es wurde nass.\n\nHört gut zu, wer immer Ihr auch seid, ich habe alle Ereignisse von dem Tag der Gezeitenwelle in meinem Tagebuch aufgeführt. Und ich weiß auch, wo zu suchen ist. Nach dem Tagebuch, nicht nach dem Fund. Helft mir, eins zu finden, damit wir das andere finden können. Oder umgekehrt! Könnt Ihr mir folgen? Gut, dann folgt mir!", sourceObjective = "Eskortiert den verwirrten Ausgrabungsleiter Wirrbart zu seinem Tagebuch. Sprecht mit Juniorarchäologe Ferd, wenn Ihr fertig seid.", completion = "Ah, Ihr konntet dem Ausgrabungsleiter helfen, sein Tagebuch zu finden! Ich hätte nie gedacht, dass es die ganze Zeit hier war.\n\nEines Tages müsst Ihr mich zu der anderen Ausgrabungsstätte bringen, von der er dauernd erzählt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13912] = { id = 13912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlammige Geheimnisse", description = "Hinter Wirrbarts vergesslichem Äußeren befindet sich der Geist eines Genies, ein Mysterium im Gewand eines Senilen. Ich werde den alten Herrn nicht aufgeben. Seht hier, was ich in seinen Notizen gefunden habe... nicht hier... nein, das ist eine Einkaufsliste... Hier, auf der Seite, auf der er versucht herauszufinden, welches Jahr es ist: die Scheibe!\n\nWir glauben, dass es sich bei diesem Artefakt der Titanen um eine Art verschlüsselte Speicherscheibe handelt. Wir waren gerade dabei, es vorsichtig auszugraben, als das Desaster losbrach und nun hoffen wir, dass es sich noch immer in den Ruinen befindet. Taucht und sucht für mich danach!", sourceObjective = "Findet eine schlammverkrustete uralte Scheibe in den Ruinen in der Nähe.", progress = "Ihr habt sie gefunden? Das ist gut. Groff möchte von hier so schnell wie möglich aufbrechen.", completion = "Spektakulär! Gute Arbeit, {name}! Wirrbart würde Euch sicher persönlich danken, wenn er sich an Euren Namen erinnern könnte.\n\nSeht Euch die Oberfläche der Scheibe an - diese mikroskopisch kleinen Verzierungen sind fantastisch. Dieses Rad enthält mit Sicherheit viele Informationen, wir müssen nur herausfinden, wie wir sie verstehen können...", sourceObjectiveStatus = "unverified-source-field" }
quests[13913] = { id = 13913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie haben unsere Gnome", description = "Der Sprengstofftrupp der Gnome, die wir aus der Tüftlerstadt angefordert haben, ist letzte Woche eingetroffen. Gerade rechtzeitig, um uns bei einem Angriff der Horde zu unterstützen. An dem Tag haben wir viele Soldaten verloren. Der Großteil der Gnomtruppen ist gefallen. Jetzt steht uns das Wasser bis zum Hals, die Silberwindzuflucht ist verloren und wir haben nur noch ein dutzend Gnome.\n\nIch flehe Euch an, helft uns, {name}. Reist nach Osten zur Silberwindzuflucht und seht Euch nach überlebenden Gnomen um. Sie wurden alle von einem großen, gnadenlosen Orc namens Thundrak weggekarrt. Findet ihn und Ihr findet unsere Gnome.", sourceObjective = "Rettet Boog den \"Zahnradflüsterer\" und Minx aus Schmerzensmeister Thundraks Wagen der nimmer endenden Agonie.", completion = "Habt Dank, {name}. Traurige Kunde bringt Ihr vom Rest der Gnomtruppe, aber zumindest konntet Ihr ein paar retten. Dafür bin ich Euch dankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[13914] = { id = 13914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sengende Rocfedern", description = "Das Junge sieht Euch für einen Moment an, ein wenig, als ob es sich fragt, ob Ihr verstehen werdet. Es kratzt ein Bild von einem Paar Federn in die Erde, bevor es mit einer Klaue auf die Lederbänder um seine Ellbogen und Knie zeigt.\n\nEs sieht nicht hungrig aus, aber wofür könnten die Federn gut sein?\n\nEs will sie wohl als Schmuck haben, wie Ihr ihn an den anderen Raptoren gesehen habt. Die größten Federn findet man bei den sengenden Rocs, welche die großen Tierknochen in der westlichen Tanariswüste umschwärmen, nordöstlich des Disteltals.", sourceObjective = "Euer Gifthautjunges möchte, das Ihr ihm 5 Federn von sengenden Rocs bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13915] = { id = 13915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sooooo hungrig", description = "Das Gifthautjunge sieht Euch erwartungsvoll an und beginnt dann, ein Piktogramm in den Boden zu kratzen.\n\nDie Zeichnungen sind grob, aber Ihr könnt die Umrisse von Dimetrodonten, Stegodonten und Pterrordaktylen ausmachen. Als der Raptor die Zeichnung vervollständigt hat, sieht er wieder zu Euch auf, fletscht seine Zähne und schnappt ein paar Mal mit dem Maul.\n\nAnscheinend hat Euer Gifthautjunges Hunger auf frisches Fleisch von diesen Tieren. Findet und tötet Dimetrodonten, Stegodonten oder Pterrordaktylen im Krater von Un'Goro und füttert Euer hungriges Junges mit ihrem Fleisch.", sourceObjective = "Euer Gifthautjunges möchte, das Ihr 15 frische Dinosaurierfleischstücke an ihn verfüttert.", sourceObjectiveStatus = "unverified-source-field" }
quests[13916] = { id = 13916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pochiert, gerührt oder roh?", description = "Der Magen des Gifthautjungen knurrt, als es mit seinen Ärmchen wedelt, um Eure Aufmerksamkeit zu bekommen. Es beginnt, die Umrisse von Silithiden in die Erde zu kratzen, darunter einige Ovale. Es sieht Euch hoffnugsvoll an und deutet auf die Kreise.\n\nSie können nur Silithideneier darstellen. Der Giftige Unterschlupf im westlichen Tanaris, nahe der Grenze zum Krater von Un'Goro, wäre sicherlich ein guter Ort, um die Eier zu finden, die Euer kleines Junges haben möchte.", sourceObjective = "Euer Gifthautjunges möchte, das Ihr 12 Silithideneier an ihn verfüttert.", sourceObjectiveStatus = "unverified-source-field" }
quests[13917] = { id = 13917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorishigelee", description = "Das Gifthautjunge sieht Euch erwartungsvoll an und beginnt dann, ein Piktogramm in den Boden zu kratzen.\n\nDie Zeichnungen des Jungen scheinen verschiedene Arten großer Insekten darzustellen, vielleicht die Gorishisilithiden. Das Junge beendet seine Zeichnung, zeigt mit einem kurzen Arm darauf, schnappt mit dem Kiefer und leckt sich das Mäulchen.\n\nEs möchte wohl, dass Ihr zur Wuchernden Narbe, im Zentrum des südlichen Kraters von Un'Goro geht und Silithidenfleisch sammelt. Wenn Ihr das Fleisch habt, gebt es Eurem hungrigen Jungen zu fressen.", sourceObjective = "Euer Gifthautjunges möchte, das Ihr 10 Stück Silithidenfleisch an ihn verfüttert.", sourceObjectiveStatus = "unverified-source-field" }
quests[13918] = { id = 13918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verbindung der Titanen", description = "Mit der Scheibe ergeben auch ein paar unserer früheren Funde jetzt mehr Sinn. Kurz nach meiner Ankunft hat Ausgrabungsleiter Wirrbart etwas gefunden, dass er für einen prähistorischen Toaster hielt.\n\nIch glaube eher, dass diese Kiste mit Öffnungen ein Lesegerät für besondere Daten ist. Leider ist es auseinandergefallen und mit dem Rest unseres Basislagers weggeschwemmt worden, als die Gezeitenwelle über uns hereinbrach!\n\nEs ist aber sicherlich nicht weit gekommen, {name}. Die Einzelteile sind bestimmt im Sand vergraben. Hier, nehmt meinen einwandfrei funktionierenden Detektor für vergrabene Artefakte, um den Strand damit abzusuchen.", sourceObjective = "Benutzt den Detektor für vergrabene Artefakte am Strand in der Nähe von Wirrbarts Ausgrabung, um 5 uralte Gerätefragmente zu finden. Fügt sie zusammen, um das uralte geschlitzte Gerät zu erhalten.", progress = "Habt Ihr alle Teile des geschlitzten Gerätes zusammengefügt? Möglicherweise müssen wir noch die Überreste von Wirrbarts Pausenbrot von der Datenschnittstelle des uralten Geräts entfernen.", completion = "Ja, ja, JA, das ist es! Seht her, dieser Schlitz hat genau die gleiche Größe wie die uralte Scheibe, genau, wie ich vermutet hatte. Hier ist Eure Belohnung, {name} - Ihr habt sie Euch redlich verdient.\n\n\n\nSeid Ihr bereit, Euch der Geschichte zu stellen? Lasst uns herausfinden, was uns die Uralten zu sagen haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[13919] = { id = 13919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ausflug zum Mondbrunnen", description = "Es hat nicht funktioniert.\n\n<Ein besorgter und verzagter Ausdruck zeichnet Pelturas' Gesicht, als er die Träne aus der Suppe entfernt und sie vorsichtig wäscht.>\n\nDer Ausbruch des Donnergipfels muss sie auf irgendeine Weise beeinträchtigt haben. Ihr müsst die Träne zum Mondbrunnen der Reinheit bringen. Er liegt noch immer unversehrt und von der Macht der Göttin beschützt am südöstlichen Fuß des Vulkans.\n\nDort wascht Ihr sie in den heiligen Wassern von Elune. Was danach geschieht, vermag ich nicht zu sagen. Ich fürchte um das Leben meiner Tochter. Es liegt nun in Euren Händen, {name}.", sourceObjective = "Nehmt Elunes Träne und reinigt sie in den Wassern des Mondbrunnens der Reinheit im Eschental.", sourceObjectiveStatus = "unverified-source-field" }
quests[13920] = { id = 13920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bevor Ihr geht...", description = "In Höllschreis Wacht wird jede Hilfe gebraucht, {name}. Aber bevor Ihr Euch auf den Weg macht, gibt es noch etwas, das hier erledigt werden muss.\n\nDie meisten unserer verderblichen Waren sind während eines Angriffs der Allianz auf See verloren gegangen. Wir müssen genug Nahrungsmittel sammeln, um den Eschentalfeldzug durchführen zu können.\n\nReist nach Osten. Dort findet Ihr reichlich Wild. Kehrt mit dem besten Fleisch zurück, das Ihr für unsere Truppen finden könnt!", sourceObjective = "Bringt 5 Hirschsteaks zu Kommandant Grimmfang in Zoram'gar.", progress = "Ja, {race}?", completion = "Dieses Wildbret sollte die Stimmung unserer Soldaten für die bevorstehende Schlacht heben. Hier habt Ihr etwas für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13921] = { id = 13921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jener, der nach Vergebung sucht", description = "<Eine Stimme aus dem Mondbrunnen durchflutet Euren Geist und gibt Euch ein Gefühl absoluten Friedens.>\n\nIhr sucht eine Heilung für das Kind, aber wisset, das alles seinen Preis hat. Im Osten liegt der Rajenbaumturm. Vor dem Turm neben dem Mondbrunnen steht jemand, welcher der Verderbnis anheimgefallen ist.\n\nAvrus Böswisper sucht Vergebung und Erlösung, {name}. Werdet Ihr ihm helfen, seinen Wunsch zu erfüllen und dadurch Euer eigenes Ziel zu erreichen?", sourceObjective = "Sprecht mit Avrus Böswisper beim Rajenbaumturm im Eschental.", completion = "<Der Satyr grinst spöttisch, aber als ihm klar wird, dass Ihr nicht hier seid, um ihn zu züchtigen, ändert sich sein Gesichtsausdruck.>\n\nEndlich naht meine Erlösung. Ich habe lange auf diesen Tag gewartet und ich glaube, ich weiß, wie ich Euch im Gegenzug dazu helfen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[13922] = { id = 13922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Händen des Widernatürlichen", description = "Mein ehemaliger Klan, die Teufelshufe von Nachtflucht, hat den Himmelssturzsee vor einiger Zeit überfallen. Sie haben Mondsteine geraubt, die in dieser Gegend einzigartig sind.\n\nDiese Mondsteine sind dafür bekannt, große Heilkräfte zu besitzen und können sicherlich dafür verwendet werden, das kleine Mädchen zu heilen, das krank in Astranaar liegt.\n\nNachtflucht liegt an der Straße im Osten, die nach Norden führt. Von ihr zweigen verschiedene Pfade in Richtung Osten ab, die in die Hügel führen und dort findet ihr meine reuelosen Brüder. Sie haben, was Ihr sucht.", sourceObjective = "Erlangt 5 gefallene Mondsteine.", progress = "Fünf Mondsteine werden benötigt, um sicherzustellen, dass das Mädchen geheilt wird.", completion = "Ihr habt alle Mondsteine, die benötigt werden. Und dennoch wird gesagt, dass ein Leben geopfert werden muss, um ein anderes zu retten.\n\nIch werde sicherstellen, dass die Mondsteine Relara um jeden Preis heilen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[13923] = { id = 13923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu Höllschreis Wacht", description = "Auf ins Schlachtgetümmel, {race}!\n\nHöllschreis Wacht ist eine unserer am stärksten umkämpften Fronten im Eschental. Die Erfahrung wird Euch nützen... vorausgesetzt, Ihr überlebt.\n\nWenn Ihr bereit seid, sprecht mit Andruk. Ich habe mit ihm besprochen, dass er Euch direkt zu Eurem Posten bringt.\n\nSobald Ihr dort eintrefft, macht Hauptmann Goggath ausfindig. Er wird Euch weitere Anweisungen erteilen.\n\nBringt Schmerz und Tod über Eure Feinde! Für die Horde!", sourceObjective = "Sprecht mit Hauptmann Goggath in Höllschreis Wacht.", completion = "Als Kind kommt ihr hierher, {race}.\n\nAls {class} der Horde mit reichlich Kampferfahrung sollt Ihr wieder gehen!\n\nEntweder das, oder Ihr endet als Rabenfutter...", sourceObjectiveStatus = "unverified-source-field" }
quests[13924] = { id = 13924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ende gut", description = "Habt Dank, dass Ihr mich von einem Schicksal errettet habt, das schlimmer ist als der Tod, {name}! Ihr habt mich und das Kind gerettet!\n\nNun, das Kind ist fast gerettet. Alles, was Ihr tun müsst, ist die Mondsteine die Straße Richtung Westen nach Astranaar zu bringen. Händigt die Steine Pelturas aus. Er wird wissen, was zu tun ist.\n\nGeht in Frieden. Elune sei gepriesen!", sourceObjective = "Überreicht die geheiligten Mondsteine Pelturas Weißmond in Astranaar im Eschental.", progress = "{name}, seid Ihr das? Seid Ihr mit dem Heilmittel für Relara zurückgekehrt?", completion = "Oh, {name}, Ihr habt meine Tochter gerettet! Ich weiß, dass die Macht der Mondsteine meiner Tochter Ihre Kraft zurückgeben wird!\n\nEure Hilfe war unermesslich wertvoll und ich kann sie Euch nie vollständig vergelten, aber... Bitte, nehmt das hier. Abgesehen von Relara, ist dies mein wertvollster Besitz.", sourceObjectiveStatus = "unverified-source-field" }
quests[13925] = { id = 13925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Stückchen Vorbeugen", description = "Seid Ihr vertraut mit den Alten, {name}? Onu und ich sind uns sicher, dass das von Euch im See gefundene Artefakt nur ihr Werk sein kann. Und es verzehrt die Dunkelküste weiterhin. Irgendetwas hat die von uns lang totgeglaubten Schrecken erweckt. Schrecken, denen weder Ihr noch ich gewachsen sind. Aber zuerst müssen wir uns um die Wildtiere kümmern.\n\nHier in diesem Schössling ist die ganze Lebensessenz, die Ihr mir gebracht habt. Ich glaube, wir können damit die Fauna der Gegend retten. Versucht es zuerst an einem nicht verzehrten Bären, Hirsch oder Mondpirscher und berichtet mir, was geschieht!", sourceObjective = "Testet den Lebensbringerschössling an einem gesunden ergrauten Distelbären, Weißschwanzhirsch, Mondpirscherpatriarchen oder einer gesunden Mondpirschermatriarchin in der Nähe.", progress = "Der Schössling, den Ihr bei Euch tragt, wächst ohne Unterbrechung an Macht. Leben ist erneuerbar, {name}. Hat es funktioniert?", completion = "Interessant... Es scheint, als könnte unser Heilmittel die Wildtiere retten, aber Ihr habt noch etwas anderes gesehen? Etwas Bösartiges, Wütendes gespürt?\n\nDas ist ein gutes Zeichen, {name}. Wer auch immer hinter diesem Problem steckt ärgert sich, und das bedeutet, das wir auf dem richtigen Weg sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[13926] = { id = 13926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleines Waisenkind Roo von den Orakeln", description = "Die Waisen haben sich auf eine Gelegenheit gefreut, einen Freund wie Euch zu treffen, {name}. Es ist wunderbar, dass Ihr zugestimmt habt, Euch um einen von ihnen zu kümmern.\n\nNehmt diese Pfeife. Mit Ihr könnt Ihr das Waisenkind rufen, das Ihr unter Eure Fittiche nehmen möchtet. Sie wird nur für begrenzte Zeit funktionieren - de facto nicht länger als die Kinderwoche selbst dauert.\n\nBitte, {name}, ruft Euer Waisenkind. Es wird sich freuen, Euch zu treffen und mit Euch zusammen die Sehenswürdigkeiten von Nordend anzusehen.", sourceObjective = "Sprecht mit Waisenmatrone Aria und benutzt dann die Pfeife des Orakelwaisenkindes, um das Waisenkind zu rufen, für das Ihr während der Kinderwoche sorgen werdet.", progress = "Du dich um uns kümmern?", completion = "Du bringst uns weg von Wauwaujungen? Gut. Wir dich schon mögen. Wauwaujunge haben alle unsere Lieblingsspielzeuge weggenommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13927] = { id = 13927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleines Waisenkind Kekek von den Wolvar", description = "Die Waisen haben sich auf eine Gelegenheit gefreut, einen Freund wie Euch zu treffen, {name}. Es ist wunderbar, dass Ihr zugestimmt habt, Euch um einen von ihnen zu kümmern.\n\nNehmt diese Pfeife. Mit Ihr könnt Ihr das Waisenkind rufen, das Ihr unter Eure Fittiche nehmen möchtet. Sie wird nur für begrenzte Zeit funktionieren - de facto nicht länger als die Kinderwoche selbst dauert.\n\nBitte, {name}, ruft Euer Waisenkind. Es wird sich freuen, Euch zu treffen und mit Euch zusammen die Sehenswürdigkeiten von Nordend anzusehen.", sourceObjective = "Sprecht mit Waisenmatrone Aria und benutzt dann die Pfeife des Wolvarwaisenkindes, um das Waisenkind zu rufen, für das Ihr während der Kinderwoche sorgen werdet.", progress = "Waisenfrau sagen, Kekek mit dir gehen.", completion = "Du bringst Kekek zum Jagen? Ist gut von alter Waisendame wegzukommen, die Kekek nicht jagen lässt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13928] = { id = 13928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet die Gefallenen", description = "Meine Schildwachen und ich haben von Bewahrer Ordanus den Befehl erhalten, hier zu bleiben und den Turm zu verteidigen. Bisher konnten wir die Horde erfolgreich zurückschlagen, aber jetzt schlagen sie einen Bogen um uns und greifen unseren Zufluchtsort im Norden direkt an.\n\nDer Bewahrer schickt seine Dryaden aus, um die Bäume zu verteidigen, aber sie scheinen der Vorhut der Kriegshymnenorcs nicht gewachsen.\n\nIhr müsst dorthin und so viele Leichen der Lachenden Schwestern einsammeln, wie Ihr könnt. Bringt sie zu Halannia im Baum am Zufluchtsort. Sie wird wissen, was zu tun ist.", sourceObjective = "Sammelt 10 Leichen der Lachenden Schwestern.", progress = "Ich bin erstaunt, dass Ihr die Reihen der Horde durchbrechen konntet und es geschafft habt, hier hereinzukommen, {race}.", completion = "Habt Dank, {class}. Wir haben alle Hände voll damit zu tun, diesen Zufluchtsort zu verteidigen, aber wenn ich wieder zu Atem komme, werde ich dafür sorgen, dass diese Schwestern ins Leben zurückkehren, wenn es der Göttin gefällt.\n\nIhr habt Euren Heldenmut bewiesen... Wir könnten Eure Hilfe gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13929] = { id = 13929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der grööößte Baum überhaupt!", description = "Bevor der große Krieg passiert war und wir das Dorf verlassen haben, wir erinnern uns dran, wie Soo-say uns vom größten von allen Bäumen erzählt hat!\n\nSoo-say es nennen Grauschlund oder so. Soo-say uns erzählen, es ist in der Mitte von den Kritzlihügeln. Nein, warte. Das nicht was Soo-say gesagt hat. Soo-say sagt Grizzlyhügel. Jetzt wir uns erinnern! Großer Baum und in der Mitte von Grizzlyhügeln. Kann gar nicht übersehen!\n\nDu uns bringen dahin, oki? Wir uns anschauen den großen Baum von innen? Soo-say sagen, große Bärenleute leben auch im Baum. Vielleicht wir sie auch sehen.", sourceObjective = "Besucht mit Eurem Waisenkind Roo den Grauschlund. Falls er nicht anwesend ist, wenn Ihr den großen Baum betretet, solltet Ihr nach ihm rufen.", completion = "Wir haben nicht gewusst, dass Bäume sooo groß werden können. Nee. Vielleicht die Großen hatten besonderen Plan für sie?", sourceObjectiveStatus = "unverified-source-field" }
